/* IPVIO Stream for Tizen - helpers (ES2017, no modules) */
'use strict';

var U = {};

U.$ = function (sel, root) { return (root || document).querySelector(sel); };

/** Creates an element: U.h('div.cls.cls2', {attr}, children...) */
U.h = function (tag, attrs) {
  var parts = tag.split('.');
  var e = document.createElement(parts[0] || 'div');
  if (parts.length > 1) e.className = parts.slice(1).join(' ');
  if (attrs) {
    for (var k in attrs) {
      if (!attrs.hasOwnProperty(k) || attrs[k] == null) continue;
      if (k === 'text') e.textContent = attrs[k];
      else if (k === 'html') e.innerHTML = attrs[k];
      else if (k === 'style') e.style.cssText = attrs[k];
      else e.setAttribute(k, attrs[k]);
    }
  }
  for (var i = 2; i < arguments.length; i++) {
    var c = arguments[i];
    if (c == null || c === false) continue;
    if (Array.isArray(c)) c.forEach(function (x) { if (x) e.appendChild(typeof x === 'string' ? document.createTextNode(x) : x); });
    else e.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
  }
  return e;
};

U.esc = function (s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
  });
};

U.clear = function (e) { while (e && e.firstChild) e.removeChild(e.firstChild); return e; };

/** HTTP GET as text with timeout. Uses XHR (works for cross-origin requests in Tizen web apps). */
U.get = function (url, timeoutMs, onProgress, headers) {
  return new Promise(function (resolve, reject) {
    var x = new XMLHttpRequest();
    x.open('GET', url, true);
    if (headers) for (var h in headers) if (headers.hasOwnProperty(h)) x.setRequestHeader(h, headers[h]);
    x.timeout = timeoutMs || 30000;
    x.onload = function () {
      if (x.status >= 200 && x.status < 300 || (x.status === 0 && x.responseText)) resolve(x.responseText);
      else reject(new Error('HTTP ' + x.status));
    };
    x.onerror = function () { reject(new Error('NET')); };
    x.ontimeout = function () { reject(new Error('TIMEOUT')); };
    if (onProgress) x.onprogress = function (ev) { onProgress(ev.loaded, ev.lengthComputable ? ev.total : 0); };
    x.send();
  });
};

/** HTTP GET as bytes (Uint8Array). */
U.getBin = function (url, timeoutMs, headers) {
  return new Promise(function (resolve, reject) {
    var x = new XMLHttpRequest();
    x.open('GET', url, true);
    x.responseType = 'arraybuffer';
    if (headers) for (var h in headers) if (headers.hasOwnProperty(h)) x.setRequestHeader(h, headers[h]);
    x.timeout = timeoutMs || 30000;
    x.onload = function () { if ((x.status >= 200 && x.status < 300 || x.status === 0) && x.response) resolve(new Uint8Array(x.response)); else reject(new Error('HTTP ' + x.status)); };
    x.onerror = function () { reject(new Error('NET')); };
    x.ontimeout = function () { reject(new Error('TIMEOUT')); };
    x.send();
  });
};

U.getJson = function (url, timeoutMs, onProgress, headers) {
  return U.get(url, timeoutMs, onProgress, headers).then(function (t) {
    t = t.replace(/^﻿/, '');
    try { return JSON.parse(t); } catch (e) { throw new Error('JSON'); }
  });
};

U.pad = function (n) { return (n < 10 ? '0' : '') + n; };

/** Seconds -> h:mm:ss or m:ss */
U.dur = function (s) {
  s = Math.max(0, Math.floor(s || 0));
  var h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), x = s % 60;
  return (h ? h + ':' + U.pad(m) : m) + ':' + U.pad(x);
};

/** Unix seconds -> HH:MM local */
U.hm = function (sec) {
  var d = new Date(sec * 1000);
  return U.pad(d.getHours()) + ':' + U.pad(d.getMinutes());
};

U.now = function () { return Math.floor(Date.now() / 1000); };

/** Time of the last remote key press (set by the app). Background work waits for a pause in key presses
 *  so it never competes with scrolling; it still runs after maxMs at the latest. */
U.lastKey = 0;
U.whenQuiet = function (fn, quietMs, maxMs) {
  var t0 = Date.now(); quietMs = quietMs || 2500; maxMs = maxMs || 20000;
  (function wait() {
    var since = Date.now() - U.lastKey;
    if (since >= quietMs || Date.now() - t0 >= maxMs) { fn(); return; }
    setTimeout(wait, Math.max(300, quietMs - since));
  })();
};

U.debounce = function (fn, ms) {
  var t = null;
  return function () {
    var a = arguments, self = this;
    clearTimeout(t);
    t = setTimeout(function () { fn.apply(self, a); }, ms);
  };
};

U.hash = function (s) {
  var h = 2166136261;
  for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(36);
};

/** Base64 (UTF-8) decode used for Xtream EPG titles; returns input if it is not valid Base64. */
U.b64 = function (s) {
  if (!s || !/^[A-Za-z0-9+/=\s]+$/.test(s) || s.length % 4 !== 0) return s || '';
  try {
    var bin = atob(s);
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    var d = new TextDecoder('utf-8').decode(bytes);
    return d.indexOf('�') >= 0 ? s : d;
  } catch (e) { return s; }
};

/** Normalises text for search (case, diacritics, Arabic letter forms). */
U.norm = function (s) {
  s = String(s || '').toLowerCase();
  if (s.normalize) s = s.normalize('NFD').replace(/[̀-ͯ]/g, '');
  return s.replace(/[\u064B-\u0655\u0670\u0640]/g, '')
    .replace(/[آأإ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي')
    .replace(/[^a-z0-9؀-ۿ]+/g, ' ').trim();
};

/** Small IndexedDB key-value store for large playlist caches. */
U.idb = (function () {
  var dbp = null;
  function open() {
    if (dbp) return dbp;
    dbp = new Promise(function (res, rej) {
      if (!window.indexedDB) { rej(new Error('no idb')); return; }
      var r = indexedDB.open('ipvio', 1);
      r.onupgradeneeded = function () { r.result.createObjectStore('kv'); };
      r.onsuccess = function () { res(r.result); };
      r.onerror = function () { rej(r.error); };
    });
    return dbp;
  }
  function tx(mode, fn) {
    return open().then(function (db) {
      return new Promise(function (res, rej) {
        var t = db.transaction('kv', mode);
        var st = t.objectStore('kv');
        var out = fn(st);
        t.oncomplete = function () { res(out && out.result !== undefined ? out.result : undefined); };
        t.onerror = function () { rej(t.error); };
        t.onabort = function () { rej(t.error); };
      });
    });
  }
  return {
    get: function (k) { return tx('readonly', function (s) { return s.get(k); }).catch(function () { return undefined; }); },
    set: function (k, v) { return tx('readwrite', function (s) { s.put(v, k); }).catch(function () {}); },
    del: function (k) { return tx('readwrite', function (s) { s.delete(k); }).catch(function () {}); }
  };
})();

U.isTizen = function () { return typeof window.tizen !== 'undefined'; };
U.hasAvplay = function () { return typeof window.webapis !== 'undefined' && webapis.avplay; };

/* While U.lazyImages is true, U.img only remembers the address; U.loadImgs() loads it later.
   Rows on the home screen use this so only pictures near the focus are downloaded and decoded. */
U.lazyImages = false;
U.img = function (src, cls, fallbackText) {
  var box = U.h('div.' + (cls || 'img'));
  if (fallbackText) box.appendChild(U.h('span.ph', { text: fallbackText }));
  if (src) {
    if (U.lazyImages) { box._src = src; box.classList.add('lz'); }
    else U.loadImg(box, src);
  }
  return box;
};
U.loadImg = function (box, src) {
  src = src || box._src;
  if (!src || box._loaded) return;
  box._loaded = true; box.classList.remove('lz');
  var im = new Image();
  im.onload = function () { box.classList.add('ok'); };
  im.onerror = function () { if (im.parentNode) im.parentNode.removeChild(im); };
  im.src = src;
  box.appendChild(im);
};
U.loadImgs = function (root) {
  if (!root) return;
  var l = root.querySelectorAll('.lz');
  for (var i = 0; i < l.length; i++) U.loadImg(l[i]);
};

U.initials = function (name) {
  var n = String(name || '').replace(/^[A-Z]{2,3}\s*[:|\-]\s*/, '').trim();
  return (n.substring(0, 3) || '?').toUpperCase();
};

/** QR code as SVG markup (uses the bundled qrcode-generator, MIT). */
U.qrSvg = function (text, size) {
  var q = qrcode(0, 'M'); q.addData(text); q.make();
  var n = q.getModuleCount(), cell = size / (n + 8), d = '';
  for (var r = 0; r < n; r++) for (var c = 0; c < n; c++) if (q.isDark(r, c)) d += 'M' + (c + 4) * cell + ' ' + (r + 4) * cell + 'h' + cell + 'v' + cell + 'h-' + cell + 'z';
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + size + ' ' + size + '" width="' + size + '" height="' + size + '">' +
    '<rect width="100%" height="100%" fill="#fff"/><path d="' + d + '" fill="#0B0F19" shape-rendering="crispEdges"/></svg>';
};

/** YouTube video id from an id, a watch/youtu.be/embed address; null if none. */
U.ytId = function (s) {
  s = String(s || '').trim();
  if (!s) return null;
  var m = /(?:v=|youtu\.be\/|embed\/|shorts\/)([\w-]{11})/.exec(s);
  if (m) return m[1];
  return /^[\w-]{11}$/.test(s) ? s : null;
};

