/* Persistent settings and user data (localStorage) */
'use strict';

/* Address of the phone page for adding playlists by QR code (see phone/index.html). */
var PHONE_PAGE = 'https://mostafaiftc-commits.github.io/ipvio-phone/';
/* TMDB key bundled for this build (the owner's own free key). */
var TMDB_DEFAULT_KEY = '3161a9c9c561f35e1c87435ddb6a1128';

var Store = (function () {
  var PFX = 'ipvio_';
  function load(k, def) {
    try { var v = localStorage.getItem(PFX + k); return v == null ? def : JSON.parse(v); } catch (e) { return def; }
  }
  function save(k, v) {
    try { localStorage.setItem(PFX + k, JSON.stringify(v)); } catch (e) { /* quota */ }
  }

  var S = {
    settings: load('settings', { lang: 'ar', aspect: 'fit', clock: true, autoNext: true }),
    playlists: load('playlists', []),          // [{id,name,type:'xtream'|'m3u',server,user,pass,url}]
    activeId: load('active', null),
    favs: load('favs', {}),                     // key plId -> { 'l123': {kind,id,name,img,...} }
    history: load('history', {}),               // plId -> [ {key,kind,name,img,t,pos,dur, ...} ] newest first
    lastLive: load('lastlive', {})              // plId -> channel key
  };

  if (S.settings.tmdbKey === undefined) S.settings.tmdbKey = TMDB_DEFAULT_KEY;
  S.saveSettings = function () { save('settings', S.settings); };
  S.savePlaylists = function () { save('playlists', S.playlists); save('active', S.activeId); };

  S.active = function () {
    for (var i = 0; i < S.playlists.length; i++) if (S.playlists[i].id === S.activeId) return S.playlists[i];
    return S.playlists[0] || null;
  };

  function plFavs() {
    var a = S.active(); if (!a) return {};
    if (!S.favs[a.id]) S.favs[a.id] = {};
    return S.favs[a.id];
  }
  S.isFav = function (key) { return !!plFavs()[key]; };
  S.toggleFav = function (item) {
    var f = plFavs();
    if (f[item.key]) delete f[item.key];
    else f[item.key] = { key: item.key, kind: item.kind, id: item.id, name: item.name, img: item.img || '', t: Date.now() };
    save('favs', S.favs);
    return !!f[item.key];
  };
  S.favList = function (kind) {
    var f = plFavs(), out = [];
    for (var k in f) if (f.hasOwnProperty(k) && (!kind || f[k].kind === kind)) out.push(f[k]);
    out.sort(function (a, b) { return b.t - a.t; });
    return out;
  };

  function plHist() {
    var a = S.active(); if (!a) return [];
    if (!S.history[a.id]) S.history[a.id] = [];
    return S.history[a.id];
  }
  /** entry: {key, kind:'live'|'movie'|'episode', name, img, pos, dur, seriesKey, seriesName, ...} */
  S.addHistory = function (entry) {
    var h = plHist();
    for (var i = h.length - 1; i >= 0; i--) {
      if (h[i].key === entry.key || (entry.seriesKey && h[i].seriesKey === entry.seriesKey)) h.splice(i, 1);
    }
    entry.t = Date.now();
    h.unshift(entry);
    if (h.length > 150) h.length = 150;
    save('history', S.history);
  };
  S.resumePos = function (key) {
    var h = plHist();
    for (var i = 0; i < h.length; i++) if (h[i].key === key) return h[i];
    return null;
  };
  S.historyList = function (kind) {
    return plHist().filter(function (e) { return !kind || e.kind === kind; });
  };
  S.continueList = function () {
    return plHist().filter(function (e) {
      return e.kind !== 'live' && e.dur > 0 && e.pos > 30 && e.pos < e.dur * 0.94;
    });
  };
  S.clearHistory = function () { var a = S.active(); if (a) S.history[a.id] = []; save('history', S.history); };

  S.setLastLive = function (key) { var a = S.active(); if (a) { S.lastLive[a.id] = key; save('lastlive', S.lastLive); } };
  S.getLastLive = function () { var a = S.active(); return a ? S.lastLive[a.id] : null; };

  /* channel chosen by hand for a match (ESPN id -> channel key), kept for two days */
  // channel chosen for a match: how = 'yellow' (chosen on purpose, always wins) or 'pick' (from the list when nothing was found)
  try { localStorage.removeItem('ipvio_matchfix'); } catch (e) {}   // picks saved by older versions overrode the schedules
  var mfix = load('matchfix2', {});
  // a channel key only means something on its own server: picks are kept per server
  function fixId(id) { var a = S.active(); return (a ? a.id : '') + '|' + id; }
  S.matchFix = function (id) { var e = mfix[fixId(id)]; return e && Date.now() - e.t < 2 * 86400000 ? e : null; };
  S.setMatchFix = function (id, key, how) {
    var now = Date.now();
    for (var k in mfix) if (mfix.hasOwnProperty(k) && now - mfix[k].t > 2 * 86400000) delete mfix[k];
    mfix[fixId(id)] = { k: key, t: now, how: how || 'pick' }; save('matchfix2', mfix);
  };
  S.clearMatchFixes = function () { mfix = {}; save('matchfix2', mfix); };
  try { localStorage.removeItem('ipvio_matchtv'); } catch (e) {}

  /* ---------- favourite teams: [{id, name, ar, logo}] (FotMob team ids) ---------- */
  S.teams = load('teams', []);
  S.isTeamFav = function (t) { return !!t && S.teams.some(function (x) { return x.id === String(t.id) || (x.name && x.name === t.name); }); };
  S.toggleTeam = function (t) {
    var on = S.isTeamFav(t);
    if (on) S.teams = S.teams.filter(function (x) { return !(x.id === String(t.id) || x.name === t.name); });
    else S.teams.push({ id: String(t.id || ''), name: t.name || '', ar: t.ar || '', logo: t.logo || '', src: t.src || 'fm' });
    save('teams', S.teams);
    return !on;
  };

  /* ---------- category order / hidden, per playlist and kind ---------- */
  var cprefs = load('catprefs', {});
  S.catPrefs = function (kind) {
    var a = S.active(); if (!a) return { order: [], hidden: {} };
    var p = (cprefs[a.id] = cprefs[a.id] || {});
    return (p[kind] = p[kind] || { order: [], hidden: {} });
  };
  S.saveCatPrefs = function () { save('catprefs', cprefs); };

  /* ---------- intro end learned per series (seconds), when IntroDB has no data ---------- */
  var intros = load('intros', {});
  S.introEnd = function (seriesKey) { return intros[seriesKey] || 0; };
  S.setIntroEnd = function (seriesKey, sec) { intros[seriesKey] = Math.round(sec); save('intros', intros); };

  /* ---------- reminders for programmes in the guide: [{key, title, start}] ---------- */
  S.reminders = load('reminders', []);
  S.saveReminders = function () { S.reminders = S.reminders.filter(function (r) { return r.start * 1000 > Date.now() - 3600000; }); save('reminders', S.reminders); };

  S.removePlaylist = function (id) {
    S.playlists = S.playlists.filter(function (p) { return p.id !== id; });
    delete S.favs[id]; delete S.history[id];
    save('favs', S.favs); save('history', S.history);
    if (S.activeId === id) S.activeId = S.playlists.length ? S.playlists[0].id : null;
    S.savePlaylists();
    U.idb.del('pl_' + id);
  };

  return S;
})();

