/* Playlist sources: Xtream Codes (player_api.php) and M3U. Builds one data model for the UI. */
'use strict';

var Src = (function () {
  var data = null;          // current playlist data
  var epgCache = {};        // streamId -> {t, list}
  var infoCache = {};

  /* ---------- account helpers ---------- */
  function normServer(s) {
    s = String(s || '').trim();
    if (!s) return '';
    if (!/^https?:\/\//i.test(s)) s = 'http://' + s;
    s = s.replace(/\/(get|player_api|xmltv)\.php.*$/i, '').replace(/\/c\/?$/i, '');
    return s.replace(/\/+$/, '');
  }
  /** A get.php / player_api.php address with username & password is an Xtream login. */
  function xtreamFromUrl(url) {
    var m = /^(https?:\/\/[^?#]+?)\/(?:get|player_api)\.php\?(.*)$/i.exec(String(url || '').trim());
    if (!m) return null;
    var q = {};
    m[2].split('&').forEach(function (p) {
      var i = p.indexOf('=');
      if (i > 0) { try { q[p.substring(0, i).toLowerCase()] = decodeURIComponent(p.substring(i + 1).replace(/\+/g, ' ')); } catch (e) { q[p.substring(0, i).toLowerCase()] = p.substring(i + 1); } }
    });
    if (!q.username || !q.password) return null;
    return { server: m[1].replace(/\/+$/, ''), user: q.username, pass: q.password };
  }
  function part(s) { return /^[A-Za-z0-9._~-]+$/.test(s) ? s : encodeURIComponent(s); }
  function api(pl, action, extra) {
    return pl.server + '/player_api.php?username=' + encodeURIComponent(pl.user) + '&password=' + encodeURIComponent(pl.pass) +
      (action ? '&action=' + action : '') + (extra || '');
  }
  function extOf(e, def) { e = String(e || '').replace(/^\./, '').trim(); return /^[A-Za-z0-9]{1,5}$/.test(e) ? e : def; }

  function streamUrl(item) {
    var pl = Store.active();
    if (item.url) return item.url;
    if (!pl || pl.type !== 'xtream') return '';
    var b = pl.server, u = part(pl.user), p = part(pl.pass);
    if (item.kind === 'live') {
      var fmt = Store.settings.liveFmt === 'm3u8' ? 'm3u8' : 'ts';
      return b + '/live/' + u + '/' + p + '/' + item.id + '.' + fmt;
    }
    if (item.kind === 'movie') return b + '/movie/' + u + '/' + p + '/' + item.id + '.' + extOf(item.ext, 'mp4');
    if (item.kind === 'episode') return b + '/series/' + u + '/' + p + '/' + item.id + '.' + extOf(item.ext, 'mp4');
    return '';
  }

  function num(v) { var n = parseFloat(v); return isNaN(n) ? 0 : n; }
  function yearOf(o, name) {
    var y = o && (o.year || o.releaseDate || o.release_date || o.releasedate);
    var m = /((?:19|20)\d{2})/.exec(String(y || '')) || /[\(\[]((?:19|20)\d{2})[\)\]]/.exec(String(name || ''));
    return m ? +m[1] : 0;
  }

  function tmdbOf(o) { var v = +(o.tmdb || o.tmdb_id || 0); return v > 0 ? v : 0; }
  var CACHE_V = 2;

  function emptyData() {
    return { live: { cats: [], items: [] }, movie: { cats: [], items: [] }, series: { cats: [], items: [] }, info: {}, loadedAt: 0 };
  }

  /* ---------- Xtream ---------- */
  async function loadXtream(pl, phase) {
    phase(T('loadingList'));
    var auth;
    try { auth = await U.getJson(api(pl), 20000); }
    catch (e) { throw new Error(e.message === 'JSON' ? T('errFormat') : T('errNet')); }
    var ui = auth && auth.user_info;
    if (!ui) throw new Error(T('errFormat'));
    if (String(ui.auth) === '0' || (ui.status && !/active/i.test(ui.status))) throw new Error(T('errLogin'));

    var d = emptyData();
    d.info = { exp: ui.exp_date ? +ui.exp_date : 0, max: ui.max_connections || '', active: ui.active_cons || '', status: ui.status || '' };

    function cats(arr) {
      return (Array.isArray(arr) ? arr : []).map(function (c) { return { id: String(c.category_id), name: String(c.category_name || '').trim() }; })
        .filter(function (c) { return c.id && c.name; });
    }
    async function safe(action, label) {
      phase(label);
      try { var r = await U.getJson(api(pl, action), 120000); return Array.isArray(r) ? r : []; } catch (e) { return []; }
    }

    d.live.cats = cats(await safe('get_live_categories', T('loadLive')));
    var lv = await safe('get_live_streams', T('loadLive'));
    d.live.items = lv.map(function (o, i) {
      return { key: 'l' + o.stream_id, kind: 'live', id: String(o.stream_id), name: String(o.name || '').trim(), img: o.stream_icon || '',
        cat: String(o.category_id != null ? o.category_id : (o.category_ids && o.category_ids[0]) || ''), num: +o.num || (i + 1),
        epg: o.epg_channel_id || '', arch: +o.tv_archive || 0 };
    });
    lv = null;

    d.movie.cats = cats(await safe('get_vod_categories', T('loadVod')));
    var vv = await safe('get_vod_streams', T('loadVod'));
    d.movie.items = vv.map(function (o) {
      return { key: 'v' + o.stream_id, kind: 'movie', id: String(o.stream_id), name: String(o.name || '').trim(), img: o.stream_icon || '',
        cat: String(o.category_id != null ? o.category_id : (o.category_ids && o.category_ids[0]) || ''), rating: num(o.rating),
        added: +o.added || 0, ext: o.container_extension || 'mp4', year: yearOf(o, o.name), tmdb: tmdbOf(o) };
    });
    vv = null;

    d.series.cats = cats(await safe('get_series_categories', T('loadSeries')));
    var sv = await safe('get_series', T('loadSeries'));
    d.series.items = sv.map(function (o) {
