/*
 * Adding a playlist from the phone with a QR code, end-to-end encrypted.
 *
 * A Tizen web app cannot run a web server, so phone and TV exchange one message through a relay
 * (ntfy). Before that the TV creates a random topic and a random 256-bit key and puts both into the
 * QR code, after the "#" of the phone page address. Browsers never send that part to any server.
 * The phone page encrypts the data with the key (NaCl secretbox: XSalsa20-Poly1305) and posts only
 * the ciphertext. The relay sees random bytes under a random topic; only this TV can open them.
 */
'use strict';

var PhoneLink = (function () {
  var open = false, topic = '', key = null, since = '', startedAt = 0, timer = null, onData = null;
  var base = '', triedHttp = false, busy = false, el = null;

  function relay() { return (Store.settings.relay || 'https://ntfy.sh').replace(/\/+$/, ''); }
  function page() { return String(Store.settings.phonePage || PHONE_PAGE || '').trim(); }

  function rnd(n) {
    var b = new Uint8Array(n);
    try { crypto.getRandomValues(b); } catch (e) { b = nacl.randomBytes(n); }
    return b;
  }
  function b64u(bytes) {
    var s = ''; for (var i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }
  function unb64u(str) {
    str = String(str || '').trim().replace(/-/g, '+').replace(/_/g, '/');
    while (str.length % 4) str += '=';
    var bin = atob(str), out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  function randomTopic() {
    var a = 'abcdefghijkmnpqrstuvwxyz23456789', b = rnd(18), s = '';
    for (var i = 0; i < b.length; i++) s += a.charAt(b[i] % a.length);
    return 'ipvio-' + s;
  }

  /** Opens an encrypted message; null if it is not for us. */
  function decrypt(msg) {
    try {
      var all = unb64u(msg);
      if (all.length < 24 + 16) return null;
      var plain = nacl.secretbox.open(all.subarray(24), all.subarray(0, 24), key);
      if (!plain) return null;
      return JSON.parse(new TextDecoder('utf-8').decode(plain));
    } catch (e) { return null; }
  }

  function status(t, err) {
    if (!el) return;
    var s = U.$('.ph-status', el); s.textContent = t; s.classList.toggle('err', !!err);
  }

  function reply(text) {
    try { var x = new XMLHttpRequest(); x.open('POST', base + '/' + topic, true); x.send(text); } catch (e) {}
  }

  function poll() {
    if (!open || busy) return;
    busy = true;
    U.get(base + '/' + topic + '/json?poll=1&since=' + (since || startedAt), 15000).then(function (txt) {
      busy = false;
      if (!open) return;
      var lines = txt.split('\n');
      for (var i = 0; i < lines.length; i++) {
        if (!lines[i].trim()) continue;
        var m; try { m = JSON.parse(lines[i]); } catch (e) { continue; }
        if (m.id) since = m.id;
        if (m.event !== 'message' || !m.message) continue;
        var data = decrypt(m.message);
        if (!data) continue;                         // replies, strangers: cannot be opened
        var ok = onData ? onData(data) : true;
        if (ok === false) { status(T('qrBad'), true); reply('bad'); continue; }
        reply('ok');
        close();
        return;
      }
    }).catch(function () {
      busy = false;
      if (!triedHttp && /^https:\/\//.test(base)) { triedHttp = true; base = base.replace(/^https:/, 'http:'); return; }
      status(T('qrNet'), true);
    });
  }

  /** mode 'playlist' | 'text'; cb(data) gets {type,server,user,pass,url,name} or {text}; return false to reject. */
  function show(mode, cb) {
    close();
    onData = cb;
    el = U.$('#phone'); U.clear(el);
    if (!page()) {
      el.appendChild(U.h('div.ph-box', null, U.h('div.ph-txt', null,
        U.h('div.ph-title', { text: T('qrTitle') }), U.h('div.ph-steps', { text: T('qrNoPage') }), U.h('div.ph-back', { text: T('phClose') }))));
      el.classList.add('show'); open = true;
      return;
    }
    topic = randomTopic(); key = rnd(32); since = ''; startedAt = Math.floor(Date.now() / 1000) - 5;
    base = relay(); triedHttp = false; busy = false;
    var link = PhoneLink.lastLink = page() + '#t=' + topic + '&k=' + b64u(key) + (relay() === 'https://ntfy.sh' ? '' : '&r=' + encodeURIComponent(relay())) + '&l=' + LANG + '&m=' + (mode || 'playlist');
    var box = U.h('div.ph-box', null,
      U.h('div.ph-qr', { html: U.qrSvg(link, 400) }),
      U.h('div.ph-txt', null,
        U.h('div.ph-title', { text: T('qrTitle') }),
        U.h('ol.ph-steps', null, [T('qr1'), mode === 'text' ? T('qr2t') : T('qr2'), T('qr3')].map(function (s) { return U.h('li', { text: s }); })),
        U.h('div.ph-status', { text: T('qrWait') }),
        U.h('div.ph-note', null, U.h('span.ic', { html: ICONS.lock }), U.h('span', { text: T('qrSecure') })),
        U.h('div.ph-back', { text: T('phClose') })));
    el.appendChild(box);
    el.classList.add('show');
