    return true;
  }

  /** Reads playlist data typed on the phone. Returns {type:'xtream',server,user,pass,name?} | {type:'m3u',url,name?} | null */
  function parseCreds(text) {
    text = String(text || '').replace(/‏|‎/g, '').trim();
    if (!text) return null;
    var urls = text.match(/https?:\/\/[^\s"'<>]+/gi) || [];
    for (var i = 0; i < urls.length; i++) {
      var x = Src.xtreamFromUrl(urls[i]);
      if (x) return { type: 'xtream', server: x.server, user: x.user, pass: x.pass };
    }
    // labelled lines: "server: …", "user: …", "pass: …" (English or Arabic)
    var lab = {};
    text.split(/\r?\n/).forEach(function (ln) {
      var m = /^\s*([A-Za-z؀-ۿ _\-]{2,24}?)\s*[:=]\s*(\S.*)$/.exec(ln);
      if (!m || /^https?$/i.test(m[1].trim())) return;
      var k = m[1].toLowerCase(), v = m[2].trim();
      if (/pass|باس|كلمة|سر/.test(k)) lab.pass = v;
      else if (/user|مستخدم|يوزر/.test(k)) lab.user = v;
      else if (/server|host|dns|url|portal|سيرفر|خادم|رابط|عنوان/.test(k)) lab.server = v;
      else if (/name|اسم/.test(k)) lab.name = v;
    });
    if (lab.server && lab.user && lab.pass) return { type: 'xtream', server: Src.normServer(lab.server), user: lab.user, pass: lab.pass, name: lab.name };
    var t = text.split(/[\s,;|]+/).filter(Boolean);
    var hostLike = function (s) { return /^https?:\/\//i.test(s) || /^[\w.-]+:\d{2,5}(\/.*)?$/.test(s) || /^[\w.-]+\.[a-z]{2,}(:\d+)?(\/.*)?$/i.test(s) || /^\d{1,3}(\.\d{1,3}){3}(:\d+)?/.test(s); };
    if (t.length >= 3 && hostLike(t[0])) return { type: 'xtream', server: Src.normServer(t[0]), user: t[1], pass: t[2] };
    if (lab.server && /^https?:\/\//i.test(lab.server)) return { type: 'm3u', url: lab.server, name: lab.name };
    if (urls.length === 1) return { type: 'm3u', url: urls[0] };
    if (t.length === 1 && hostLike(t[0]) && /\.m3u8?(\?|$)|\/get\.php/i.test(t[0])) return { type: 'm3u', url: 'http://' + t[0] };
    return null;
  }

  /** Normalises what the phone page sent into the playlist form's shape, or null. */
  function toPlaylist(d) {
    if (!d) return null;
    if (d.text) return parseCreds(d.text);
    if (d.type === 'm3u' && d.url) {
      var x = Src.xtreamFromUrl(d.url);
      if (x) return { type: 'xtream', server: x.server, user: x.user, pass: x.pass, name: d.name };
      return { type: 'm3u', url: /^https?:\/\//i.test(d.url) ? d.url : 'http://' + d.url, name: d.name };
    }
    if (d.server && d.user && d.pass) {
      var y = Src.xtreamFromUrl(d.server);
      if (y) return { type: 'xtream', server: y.server, user: y.user, pass: y.pass, name: d.name };
      return { type: 'xtream', server: Src.normServer(d.server), user: d.user, pass: d.pass, name: d.name };
    }
    if (d.server) return parseCreds(d.server);
    return null;
  }

  return { show: show, close: close, key: key_, isOpen: function () { return open; }, parseCreds: parseCreds, toPlaylist: toPlaylist,
    _test: { b64u: b64u, unb64u: unb64u } };
})();

files.tube:
/*
 * YouTube trailers inside the app.
 * One iframe (#yt) shows the trailer host page (yt.html on the GitHub Pages site next to the phone page),
 * which runs the official YouTube IFrame Player. The app controls it with postMessage and keeps the
 * remote-control focus itself. The same iframe is reused for home-screen previews and full trailers,
 * so the YouTube player loads only once.
 */
'use strict';

var Tube = (function () {
  var frame = null, ready = false, failed = false, queue = null, loadTimer = null;
  var job = null;             // {ids, i, opts, on}
  var box = null;
  var adIds = {};             // trailers that started with a YouTube ad (skipped for previews)

  function hostUrl() {
    var p = String(Store.settings.phonePage || PHONE_PAGE || '').trim();
    if (!p) return '';
    return p.replace(/[#?].*$/, '').replace(/[^\/]*$/, '') + 'yt.html';
  }
  function origin() { var m = /^(https?:\/\/[^\/]+)/.exec(hostUrl()); return m ? m[1] : ''; }

  function ensure() {
    if (frame || failed) return;
    var url = hostUrl();
    if (!url) { failed = true; return; }
    box = U.$('#yt');
    frame = U.h('iframe', { src: url, allow: 'autoplay; encrypted-media', frameborder: '0', tabindex: '-1', scrolling: 'no' });
    frame.onload = function () { try { window.focus(); } catch (e) {} };
    box.appendChild(frame);
    loadTimer = setTimeout(function () {
      if (ready) return;
      failed = true;
      if (job && job.on) job.on({ ev: 'fail', reason: 'host' });
    }, 15000);
  }

  window.addEventListener('message', function (ev) {
    var m;
    try { m = typeof ev.data === 'string' ? JSON.parse(ev.data) : ev.data; } catch (e) { return; }
    if (!m || m.src !== 'ipvio-yt') return;
    if (origin() && ev.origin && ev.origin !== origin() && ev.origin !== 'null') return;
    if (m.ev === 'ready') {
      ready = true; clearTimeout(loadTimer);
      if (queue) { send(queue); queue = null; }
      return;
    }
    if (!job) return;
    if (m.ev === 'error') {
      // 2/5/100/101/150: bad id, not playable, removed or embedding not allowed -> next candidate
      job.i++;
      if (job.i < job.ids.length) { load(); return; }
      var on = job.on; job = null; setMode('');
      if (on) on({ ev: 'fail', reason: 'video', code: m.code });
      return;
    }
    if (job.on) job.on(m);
  });

  function send(o) {
    o.to = 'ipvio-yt';
    if (!ready || !frame) { queue = o; return; }
    try { frame.contentWindow.postMessage(JSON.stringify(o), '*'); } catch (e) {}
  }

  function setMode(mode) {
    box = box || U.$('#yt');
    box.className = mode ? 'on ' + mode : '';
    if (frame) frame.style.visibility = mode ? '' : 'hidden';   // nothing of the player is drawn while idle
  }

  function load() {
    var o = job.opts;
    send({ cmd: 'load', id: job.ids[job.i], start: o.start || 0, mute: !!o.mute, q: o.q || 'hd720', vol: o.vol || 100,
      cc: Store.settings.trailerSubs === false ? '' : 'ar' });
  }

  /** ids: YouTube ids in order of preference; opts {mode:'preview'|'full', mute, q, start}; on(msg) gets state/time/fail */
  function play(ids, opts, on) {
    ids = (ids || []).filter(Boolean);
    if (!ids.length) { if (on) on({ ev: 'fail', reason: 'none' }); return; }
    ensure();
    if (failed) { if (on) on({ ev: 'fail', reason: 'host' }); return; }
    job = { ids: ids, i: 0, opts: opts || {}, on: on };
    setMode(job.opts.mode || 'preview');
    box.classList.remove('show');
    load();
    return job;
  }
  function show() { if (box) box.classList.add('show'); }
  /** Stops playback; with an argument only if that job is still the current one. */
  function stop(only) {
    if (only !== undefined && only !== job) return;
    if (!job && !(box && box.className)) return;
    job = null;
    send({ cmd: 'stop' });
    if (box) box.classList.remove('show');
    setTimeout(function () { if (!job) setMode(''); }, 600);
  }
  /** Loads the player early (home screen), so the first preview starts fast. */
  function warm() { ensure(); }
  /** Removes the YouTube frame completely (its video layer cannot show through anything); made again when needed. */
  function destroy() {
    job = null; queue = null; ready = false; failed = false; clearTimeout(loadTimer);
    if (frame && frame.parentNode) frame.parentNode.removeChild(frame);
    frame = null;
    if (box) box.className = '';
  }

  return {
    play: play, stop: stop, show: show, warm: warm, destroy: destroy,
    toggle: function () { send({ cmd: 'toggle' }); },
    unmute: function () { send({ cmd: 'unmute', vol: 100 }); },
    /** Skips to the next candidate; false if there is none. */
    next: function () { if (!job || job.i + 1 >= job.ids.length) return false; job.i++; load(); return true; },
    currentId: function () { return job ? job.ids[job.i] : null; },
    markAd: function (id) { if (id) adIds[id] = 1; },
    withoutAds: function (ids) { return (ids || []).filter(function (k) { return !adIds[k]; }); },
    seek: function (by) { send({ cmd: 'seek', by: by }); },
    available: function () { return !!hostUrl() && !failed; },
    active: function () { return !!job; }
  };
})();

files.tmdb:
/*
 * TMDB (optional, user's own free key): trending, box office, details and official trailers.
 * Titles from TMDB are matched against the user's own playlist, so everything shown on the
 * home screen can be played directly. Without a key the app falls back to provider data.
 */
'use strict';

var TMDB = (function () {
  var mem = {};          // url -> {t, data}
  var ix = null, ixData = null;

  function key() { return String(Store.settings.tmdbKey || '').trim(); }
  function has() { return !!key(); }
  function base() { return (Store.settings.tmdbBase || 'https://api.themoviedb.org/3').replace(/\/+$/, ''); }
  function img(path, size) {
    if (!path) return '';
    if (/^https?:\/\//.test(path)) return path;
    return (Store.settings.tmdbImg || 'https://image.tmdb.org/t/p/') + (size || 'w780') + path;
  }
  function lang() { return LANG === 'ar' ? 'ar' : 'en-US'; }

  /** GET with in-memory cache. params.language === null leaves the language out. */
  function get(path, params, ttlMin, k) {
    k = k || key();
    var bearer = k.length > 40;
    var q = bearer ? [] : ['api_key=' + encodeURIComponent(k)];
    params = params || {};
    if (params.language === undefined) params.language = lang();
    for (var p in params) if (params.hasOwnProperty(p) && params[p] !== null && params[p] !== '') q.push(p + '=' + encodeURIComponent(params[p]));
    var url = base() + path + '?' + q.join('&');
    var c = mem[url];
    if (c && Date.now() - c.t < (ttlMin || 360) * 60000) return Promise.resolve(c.data);
    var headers = bearer ? { Authorization: 'Bearer ' + k, Accept: 'application/json' } : null;
    return U.getJson(url, 15000, null, headers).then(function (d) { mem[url] = { t: Date.now(), data: d }; return d; });
  }

  /** Checks a key. Resolves true/false. */
  function check(k) {
    k = String(k || '').trim();
    if (!k) return Promise.resolve(false);
    return get('/configuration', { language: null }, 1, k).then(function (d) { return !!(d && d.images); }).catch(function () { return false; });
  }

  /* ---------- matching TMDB titles with the playlist ---------- */
  function clean(name) {
    var s = String(name || '');
    s = s.replace(/^\s*[\[(|]?\s*[A-Za-z]{2,4}\s*[\])|:\-–]\s*/, '');           // "EN - ", "|AR| ", "[FR] "
    s = s.replace(/^\s*[\[(|]?\s*[A-Za-z]{2,4}\s*[\])|:\-–]\s*/, '');
    s = s.replace(/[\[(]\s*(19|20)\d{2}\s*[\])]/g, ' ').replace(/\s(19|20)\d{2}\s*$/, ' ');
    s = s.replace(/\b(4k|uhd|fhd|hd|sd|hevc|x265|h265|h264|multi|vostfr|dubbed|subbed|multisub|cam|ts)\b/gi, ' ');
    s = s.replace(/(مترجم|مدبلج|كامل)/g, ' ');
    return s;
  }
  function norm(name) { return U.norm(clean(name)); }

  function buildIndex() {
    var d = Src.data();
    if (ix && ixData === d) return ix;
    ixData = d;
    ix = { movie: { id: {}, name: {} }, series: { id: {}, name: {} } };
    ['movie', 'series'].forEach(function (k) {
      Src.list(k).forEach(function (it) {
        if (it.tmdb) ix[k].id[it.tmdb] = it;
        var n = norm(it.name);
        if (n) (ix[k].name[n] || (ix[k].name[n] = [])).push(it);
      });
    });
    return ix;
  }

  /** TMDB result -> playlist item or null. kind 'movie' | 'series' */
  function match(kind, r) {
    if (!Src.data()) return null;
    var I = buildIndex()[kind];
    if (I.id[r.id]) return I.id[r.id];
    var y = +String(r.release_date || r.first_air_date || '').substring(0, 4);
    var names = [r.title || r.name, r.original_title || r.original_name];
    for (var i = 0; i < names.length; i++) {
      var list = I.name[norm(names[i])];
      if (!list) continue;
      for (var j = 0; j < list.length; j++) if (!y || !list[j].year || Math.abs(list[j].year - y) <= 1) return list[j];
    }
    return null;
  }

  function entry(kind, r, it, rank) {
    return {
      item: it, rank: rank || 0,
      title: r.title || r.name || it.name,
      plot: r.overview || '',
      year: +String(r.release_date || r.first_air_date || '').substring(0, 4) || it.year,
      rating: r.vote_average || it.rating,
      backdrop: img(r.backdrop_path, 'w1280'),
      backdropSmall: img(r.backdrop_path, 'w780'),
      poster: img(r.poster_path, 'w342') || it.img,
      tmdbId: r.id, kind: kind
    };
  }

  async function pages(path, params, n) {
    var out = [];
    for (var p = 1; p <= n; p++) {
      var o = Object.assign({ page: p, language: 'en-US' }, params || {});
      try { var d = await get(path, o, 360); out = out.concat((d && d.results) || []); } catch (e) { break; }
    }
    return out;
  }

  function matchAll(kind, results, max) {
    var out = [], seen = {};
    results.forEach(function (r, i) {
      if (out.length >= max) return;
      var it = match(kind, r);
      if (it && !seen[it.key]) { seen[it.key] = 1; out.push(entry(kind, r, it, i + 1)); }
    });
    out.forEach(function (e, i) { e.rank = i + 1; });
    return out;
  }

  /** A list mixing films and series ([{kind, r}]), kept in order. */
  function matchMixed(list, max) {
    var out = [], seen = {};
    list.forEach(function (x) {
      if (out.length >= max) return;
      var it = match(x.kind, x.r);
      if (it && !seen[it.key]) { seen[it.key] = 1; out.push(entry(x.kind, x.r, it, out.length + 1)); }
    });
    return out;
  }
  function interleave(a, b, ka, kb) {
    var out = [];
    for (var i = 0; i < Math.max(a.length, b.length); i++) { if (a[i]) out.push({ kind: ka, r: a[i] }); if (b[i]) out.push({ kind: kb, r: b[i] }); }
    return out;
  }
  /** Lists for the home screen (only titles found in the playlist), like the rows of the big streaming apps:
   *  trending, box office, popular on streaming in Egypt, Arabic and Turkish series, Egyptian films, genres. */
  async function home() {
    if (!has() || !Src.data()) return null;
    var pl = Store.active();
    var ck = 'tmdb_home3_' + (pl ? pl.id : '');
    var c = await U.idb.get(ck);
    if (c && Date.now() - c.t < 6 * 3600000) return c.data;
    var today = new Date(), from = new Date(Date.now() - 200 * 86400000);
    function ds(d) { return d.getFullYear() + '-' + U.pad(d.getMonth() + 1) + '-' + U.pad(d.getDate()); }
    var pop = { sort_by: 'popularity.desc' }, streamEG = { watch_region: 'EG', with_watch_monetization_types: 'flatrate|free|ads|rent', sort_by: 'popularity.desc' };
    var genre = function (g) { return pages('/discover/movie', { with_genres: g, sort_by: 'popularity.desc', 'vote_count.gte': 150 }, 2); };
    var r = await Promise.all([
      pages('/trending/movie/week', {}, 3), pages('/trending/tv/week', {}, 2),
      pages('/discover/movie', { sort_by: 'revenue.desc', 'primary_release_date.gte': ds(from), 'primary_release_date.lte': ds(today) }, 2), pages('/movie/now_playing', {}, 1),
      pages('/discover/movie', streamEG, 2), pages('/discover/tv', streamEG, 2),
      pages('/discover/tv', Object.assign({ with_original_language: 'ar' }, pop), 3),
      pages('/discover/movie', Object.assign({ with_origin_country: 'EG' }, pop), 3),
      pages('/discover/tv', Object.assign({ with_original_language: 'tr' }, pop), 2),
      genre(28), genre(35), genre(27), genre(16)
    ].map(function (p) { return p.catch(function () { return []; }); }));
    var data = {
      trendMovies: matchAll('movie', r[0], 20),
      trendSeries: matchAll('series', r[1], 20),
      boxOffice: matchAll('movie', r[2].concat(r[3]), 20),
      egTrend: matchMixed(interleave(r[5], r[4], 'series', 'movie'), 20),
      arSeries: matchAll('series', r[6], 25),
      egMovies: matchAll('movie', r[7], 25),
      trSeries: matchAll('series', r[8], 20),
      gAction: matchAll('movie', r[9], 20), gComedy: matchAll('movie', r[10], 20), gHorror: matchAll('movie', r[11], 20), gAnim: matchAll('movie', r[12], 20)
    };
    // keep only plain data for the cache; items are looked up again by key
    var store = {};
    for (var k in data) store[k] = data[k].map(function (e) { var x = Object.assign({}, e); x.key = e.item.key; delete x.item; return x; });
    U.idb.set(ck, { t: Date.now(), data: store });
    return store;
  }
  /** "Because you watched …": titles like this one that are on the server (kept for a day). */
  async function forYou(item) {
    if (!has()) return [];
    var id = await idFor(item);
    if (!id) return [];
    var tv = item.kind === 'series', kind = tv ? 'series' : 'movie', ck = 'tmdb_rec_' + (tv ? 't' : 'm') + id;
    var c = await U.idb.get(ck), list;
    if (c && Date.now() - c.t < 86400000) list = c.data;
    else {
      var base = (tv ? '/tv/' : '/movie/') + id;
      list = (await pages(base + '/recommendations', {}, 2).catch(function () { return []; }));
      if (list.length < 30) list = list.concat(await pages(base + '/similar', {}, 1).catch(function () { return []; }));
      list = list.map(function (x) { return { id: x.id, title: x.title, name: x.name, original_title: x.original_title, original_name: x.original_name, overview: x.overview,
        release_date: x.release_date, first_air_date: x.first_air_date, vote_average: x.vote_average, backdrop_path: x.backdrop_path, poster_path: x.poster_path }; });
      U.idb.set(ck, { t: Date.now(), data: list });
    }
    return matchAll(kind, list, 20).filter(function (e) { return e.item.key !== item.key; });
  }
  /** Resolves cached entries (with key) back to playlist items. */
  function resolve(list) {
    return (list || []).map(function (e) {
      var it = Src.find(e.key); if (!it) return null;
      if (!it.tmdb && e.tmdbId && !it._tmdbId) { it._tmdbId = e.tmdbId; it._tmdbTried = true; }     // known: no search needed
      var x = Object.assign({}, e); x.item = it; return x;
    }).filter(Boolean);
  }

  async function idFor(item) {
    if (item.tmdb) return item.tmdb;
    if (item._tmdbTried) return item._tmdbId || 0;
    item._tmdbTried = true;
    var tv = item.kind === 'series';
    var p = { query: clean(item.name).trim(), language: 'en-US' };
    if (item.year) p[tv ? 'first_air_date_year' : 'year'] = item.year;
    try {
      var d = await get(tv ? '/search/tv' : '/search/movie', p, 720);
      var r = d && d.results && d.results[0];
      item._tmdbId = r ? r.id : 0;
    } catch (e) { item._tmdbId = 0; }
    return item._tmdbId;
  }

  /* ---------- age rating and content advisories (like the big streaming apps: "+18  violence, language, nudity") ---------- */
  var RATE_C = ['EG', 'SA', 'AE', 'US', 'GB', 'DE', 'FR', 'NL', 'ES', 'BR', 'KR'];
