/*
 * Player extras for movies and episodes:
 *  - Subtitles chosen by the user: the file's own tracks, or Arabic/English subtitles found online
 *    (OpenSubtitles, by IMDb id from TMDB, else by name), with a sync adjustment. The chosen subtitle
 *    is kept for that movie/episode and comes back when it is played again.
 *  - Skip intro / recap: times from IntroDB (community database, by IMDb id + season/episode); when it
 *    has nothing, a skip button that learns where this series' intro ends from the user's own skips.
 *    IntroDB's end-credits time also brings the "next episode" prompt at the right moment.
 */
'use strict';

var Subs = (function () {
  var OS_HEAD = { 'X-User-Agent': 'TemporaryUserAgent' };
  function base() { return (Store.settings.osBase || 'https://rest.opensubtitles.org').replace(/\/+$/, ''); }

  async function imdbFor(ctx) {
    if (!TMDB.has()) return { imdb: '', title: '' };
    try { var d = await TMDB.details(ctx.series || ctx.item); return { imdb: d && d.imdb || '', title: d && (d.original || d.title) || '' }; }
    catch (e) { return { imdb: '', title: '' }; }
  }
  /** Search results [{id, name, lang, dl, enc, n}] best first. lang 'ara' | 'eng' */
  async function search(ctx, lang) {
    var it = ctx.item, ep = it.kind === 'episode';
    var t = await imdbFor(ctx);
    var num = String(t.imdb || '').replace(/^tt0*/, '');
    var name = (t.title || TMDB.clean(ctx.series ? ctx.series.name : it.name)).trim().toLowerCase().replace(/\s+/g, ' ');
    var urls = [];
    if (ep) {
      if (num) urls.push('/search/episode-' + it.ep + '/imdbid-' + num + '/season-' + it.season + '/sublanguageid-' + lang);
      urls.push('/search/episode-' + it.ep + '/query-' + encodeURIComponent(name) + '/season-' + it.season + '/sublanguageid-' + lang);
    } else {
      if (num) urls.push('/search/imdbid-' + num + '/sublanguageid-' + lang);
      urls.push('/search/query-' + encodeURIComponent(name) + '/sublanguageid-' + lang);
    }
    for (var i = 0; i < urls.length; i++) {
      try {
        var r = await U.getJson(base() + urls[i], 20000, null, OS_HEAD);
        var out = [], seen = {};
        (Array.isArray(r) ? r : []).forEach(function (s) {
          if (!s.SubDownloadLink || seen[s.IDSubtitleFile] || !/^(srt|vtt|txt|sub)$/i.test(s.SubFormat || 'srt')) return;
          if (ep && (+s.SeriesSeason && +s.SeriesSeason !== it.season || +s.SeriesEpisode && +s.SeriesEpisode !== it.ep)) return;
          seen[s.IDSubtitleFile] = 1;
          out.push({ id: s.IDSubtitleFile, name: String(s.SubFileName || s.MovieReleaseName || '').replace(/\.(srt|vtt|sub|txt)$/i, ''), lang: lang,
