      var m = /(\d+):(\d{2}):(\d{2})[,.](\d{1,3})\s*-->\s*(\d+):(\d{2}):(\d{2})[,.](\d{1,3})/.exec(lines[i]) ||
        /()(\d{1,2}):(\d{2})[,.](\d{1,3})\s*-->\s*()(\d{1,2}):(\d{2})[,.](\d{1,3})/.exec(lines[i]);
      if (!m) return;
      function ms(h, mi, s, f) { return ((+h || 0) * 3600 + (+mi) * 60 + (+s)) * 1000 + +((f + '00').slice(0, 3)); }
