var PlayExtras = (function () {
  var ctx = null, cues = null, offset = 0, ci = 0, subT = null, lastText = null;
  var seg = null, skipTarget = 0, skipKind = '', learn = null, guessUsed = false, outroAt = 0;

  function el() { return U.$('#subs'); }
  function subKey() { return ctx && ctx.item ? 'sub_' + ctx.item.key : ''; }

  /* ---------- external subtitles ---------- */
  function render() {
