      e.appendChild(U.h('div.al-rem', null, ch ? U.img(ch.img, 'al-chl', U.initials(ch.name)) : null,
        U.h('div', null, U.h('b', { text: a.r.title }), U.h('div.al-sub', { text: (ch ? ch.name : '') + '  ·  ' + U.hm(a.r.start) }))));
    } else {
