      var msg = a.kind === 'soon' ? T('alSoon') : a.kind === 'ko' ? T('alKo') : a.kind === 'ft' ? T('alFt') : T('alGoal') + '  ' + Sports.title(a.side === 'home' ? g.home : g.away);
      e.appendChild(U.h('div.al-top', null, U.h('span.al-ic', { html: a.kind === 'goal' ? MI.ball : a.kind === 'ft' ? MI.star : MI.bell }), U.h('span', { text: msg }),
        U.h('span.al-lg', { text: g.league })));
      function side(t) { return U.h('div.al-team', null, U.img(t.logo, 'al-logo', U.initials(t.name)), U.h('span', { text: Sports.title(t) })); }
      e.appendChild(U.h('div.al-mid', null, side(g.home),
        g.state === 0 ? U.h('div.al-score', { text: U.hm(g.start) }) : U.h('div.al-score', null, U.h('span', { text: String(g.home.score || 0) }), U.h('i', { text: '-' }), U.h('span', { text: String(g.away.score || 0) })), side(g.away)));
