CatScreen.prototype.destroy = function () { Src.catsChanged(); };
CatScreen.prototype.key = function (k) {
  var self = this, items = this.list.items, i = this.list.idx;
  if (this.moving) {
    if (k === 'up' || k === 'down') {
      var j = i + (k === 'up' ? -1 : 1);
      if (j < 0 || j >= items.length) return true;
      var t = items[i]; items[i] = items[j]; items[j] = t;
      this.list.idx = j; this.save(); this.redraw(); return true;
