/*
 * NewEps: new episodes of the series the user follows (favourites + series from the watch history).
 *   Every 3 hours the episode lists of those series are read again from the server and compared with
 *   what was there before; episodes that appeared since are listed on Home ("New episodes") and the
 *   series poster gets a "new" mark, until the episode is played (or after 14 days).
 * Pick: "What should I watch?" — a random movie or series, by genre (TMDB, when there is a key) or by
 *   the server's own categories, skipping what was already watched; "Another suggestion" shuffles again.
 */
'use strict';

var NewEps = (function () {
  var st = null, plId = null, timer = null, busy = false, listeners = [];
  function key() { var a = Store.active(); return a ? 'eptrack_' + a.id : ''; }
  function loadState() {
    var a = Store.active();
    if (st && plId === (a && a.id)) return Promise.resolve(st);
    plId = a && a.id;
    return U.idb.get(key()).then(function (v) { st = v || { series: {}, items: [], last: 0 }; return st; });
  }
  function save() { if (st) U.idb.set(key(), st); }
  function followed() {
    var out = [], seen = {};
    function add(k) { var it = Src.find(k); if (it && it.kind === 'series' && !seen[k]) { seen[k] = 1; out.push(it); } }
    Store.favList('series').forEach(function (f) { add(f.key); });
    Store.historyList('episode').forEach(function (h) { if (out.length < 20) add(h.seriesKey); });
    return out.slice(0, 20);
  }
  function prune() {
    var now = Date.now();
    st.items = st.items.filter(function (x) {
      if (now - x.t > 14 * 86400000) return false;
      var h = Store.resumePos(x.eKey);
      return !(h && h.pos > 60);                    // played: no longer new
    });
  }
  async function check(force) {
    var pl = Store.active();
    if (busy || !pl || pl.type !== 'xtream' || !Src.data()) return;
    await loadState();
    if (!force && Date.now() - (st.last || 0) < 3 * 3600000) { var n0 = st.items.length; prune(); if (st.items.length !== n0) fire(); return; }
    busy = true;
    var series = followed().slice(0, 12), changed = false;
    for (var i = 0; i < series.length; i++) {
      var it = series[i];
      // one series at a time with a pause, never while something plays: the TV stays smooth
      await new Promise(function (r) { setTimeout(function () { U.whenQuiet(r, 4000, 60000); }, 4000); });
      while (Player.isActive()) await new Promise(function (r) { setTimeout(r, 30000); });
      try {
        var info = await Src.seriesInfo(it, true);
        var eps = [];
        info.seasons.forEach(function (s) { (info.eps[s] || []).forEach(function (e) { eps.push(e); }); });
        var keys = eps.map(function (e) { return e.key; });
        var rec = st.series[it.key];
        if (rec && rec.known) {
          var known = {}; rec.known.forEach(function (k) { known[k] = 1; });
          eps.forEach(function (e) {
            if (known[e.key]) return;
            st.items.unshift({ sKey: it.key, eKey: e.key, season: e.season, ep: e.ep, name: e.name || '', img: e.img || it.img, t: Date.now() });
            changed = true;
          });
        }
        st.series[it.key] = { known: keys, t: Date.now() };     // first look: this is the baseline
      } catch (e) {}
    }
    st.last = Date.now();
