    timer = setInterval(function () { check(false); }, 3 * 3600000);
  }
  function list() { return st && plId === (Store.active() && Store.active().id) ? st.items.slice() : []; }
  function has(seriesKey) { return list().some(function (x) { return x.sKey === seriesKey; }); }
  function seen(eKey) {
