/* ---------- What should I watch? ---------- */
var Pick = (function () {
  var shown = {};          // suggested this session, not repeated
  var GEN = {
    movie: [[28, 'gAction'], [35, 'gComedy'], [18, 'gDrama'], [27, 'gHorror'], [53, 'gThriller'], [10749, 'gRomance'], [878, 'gScifi'], [80, 'gCrime'], [16, 'gAnim'], [10751, 'gFamily'], [12, 'gAdventure'], ['ar', 'gArabic']],
    series: [[10759, 'gAction'], [35, 'gComedy'], [18, 'gDrama'], [80, 'gCrime'], [9648, 'gMystery'], [10765, 'gScifi'], [16, 'gAnim'], [10751, 'gFamily'], ['ar', 'gArabic'], ['tr', 'gTurkish'], ['ko', 'gKorean']]
  };
  function watched(it) {
    if (it.kind === 'movie') { var h = Store.resumePos(it.key); return !!(h && h.pos > 300); }
    return Store.historyList('episode').some(function (x) { return x.seriesKey === it.key; });
  }
  /** Items of one TMDB genre / original language that are on the server. */
  async function byGenre(kind, g) {
    var out = [], seen = {};
    var p = { sort_by: 'popularity.desc', 'vote_count.gte': kind === 'movie' ? 150 : 60, language: 'en-US' };
    if (typeof g === 'number') p.with_genres = g; else p.with_original_language = g;
    for (var page = 1; page <= 6 && out.length < 60; page++) {
      try {
        var d = await TMDB.discover(kind === 'movie' ? 'movie' : 'tv', Object.assign({ page: page }, p));
        (d && d.results || []).forEach(function (r) { var it = TMDB.match(kind, r); if (it && !seen[it.key]) { seen[it.key] = 1; it._vote = r.vote_average; out.push(it); } });
        if (!d || !d.results || !d.results.length) break;
      } catch (e) { break; }
    }
    return out;
  }
  function choose(pool) {
    var fresh = pool.filter(function (it) { return !shown[it.key] && !watched(it); });
    if (!fresh.length) { shown = {}; fresh = pool.filter(function (it) { return !watched(it); }); }
    if (!fresh.length) fresh = pool;
    if (!fresh.length) return null;
    var good = fresh.filter(function (it) { return (it._vote || it.rating || 0) >= 6.5; });   // rated ones first when there are enough
    var from = good.length >= 5 ? good : fresh;
    var it = from[Math.floor(Math.random() * from.length)];
    shown[it.key] = 1;
    return it;
  }
  function openWith(pool, label) {
    var it = choose(pool);
    if (!it) { Toast(T('pickNone')); return; }
    var shuffle = function () { return choose(pool); };
    var s = it.kind === 'movie' ? new DetailScreen(it, { shuffle: shuffle, label: label }) : new SeriesScreen(it, { shuffle: shuffle, label: label });
    var top = App._debug().stack; var cur = top[top.length - 1];
    if (cur && cur.opt && cur.opt.shuffle) App.replace(s); else App.push(s);
  }
  /** kind 'movie'|'series'; catId: a server category to pick from directly (Browse screen). */
  function open(kind, catId) {
    if (catId) { openWith(Src.list(kind, catId), ''); return; }
    var opts = [{ label: T('pickAny'), value: 'any' }];
    if (TMDB.has()) GEN[kind].forEach(function (x) { opts.push({ label: T(x[1]), value: 'g:' + x[0] }); });
    opts.push({ label: T('pickByCat'), value: 'cat' });
    Modal.pick(T('pickTitle') + ' — ' + T(kind === 'movie' ? 'movies' : 'series'), opts, function (v) {
      if (!v) return;
      if (v === 'any') { openWith(Src.list(kind), T('pickAny')); return; }
      if (v === 'cat') {
        Modal.pick(T('pickByCat'), Src.visibleCats(kind).map(function (c) { return { label: c.name, value: c.id }; }), function (id) {
          if (id) openWith(Src.list(kind, id), '');
        });
        return;
      }
      var g = v.slice(2); g = /^\d+$/.test(g) ? +g : g;
      Loader.show(T('pickLooking'));
      byGenre(kind, g).then(function (pool) {
        Loader.hide();
        if (pool.length < 2) { Toast(T('pickFew')); if (!pool.length) return; }
        var lb = ''; GEN[kind].forEach(function (x) { if (x[0] === g) lb = T(x[1]); });
        openWith(pool, lb);
      }).catch(function () { Loader.hide(); Toast(T('errNet')); });
    });
  }
  return { open: open };
})();

/** "Another suggestion" button for a screen opened by Pick. */
function shuffleBtn(opt) {
  var b = U.h('div.btn', null, U.h('span.ic', { html: '<svg viewBox="0 0 24 24"><path d="M16 3h5v5M4 20L21 3M21 16v5h-5M15 15l6 6M4 4l5 5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>' }), U.h('span', { text: T('pickAgain') }));
