      sc.sort(function (a, b) { return a.w - b.w; });
      if (g.tvExt && g.tvExt.length) title = T('tvOutHint') + ' ' + g.tvExt.slice(0, 4).join(' · ') + '\n' + (sc.some(function (o) { return o.w < 99; }) ? title : T('tvNotHere'));
      var opts = sc.length ? sc : Src.list('live').slice(0, 400).map(function (ch) { return { label: ch.name, value: ch.key }; });
