  var p = this.pl ? Object.assign({}, this.pl) : { id: 'p' + Date.now().toString(36) };
  p.type = this.type;
  if (this.type === 'm3u') {
    if (!v.url) { this.err.textContent = T('errFields'); return; }
    var x = Src.xtreamFromUrl(v.url);
    if (x) { p.type = 'xtream'; p.server = x.server; p.user = x.user; p.pass = x.pass; delete p.url; }
    else { p.url = /^https?:\/\//i.test(v.url) ? v.url : 'http://' + v.url; delete p.server; }
  } else {
    if (!v.server || !v.user || !v.pass) { this.err.textContent = T('errFields'); return; }
    var x2 = Src.xtreamFromUrl(v.server);
    if (x2) { p.server = x2.server; p.user = x2.user; p.pass = x2.pass; }
    else { p.server = Src.normServer(v.server); p.user = v.user; p.pass = v.pass; }
    delete p.url;
  }
