    Loader.hide();
    if (isNew) Store.playlists.push(p);
    else Store.playlists = Store.playlists.map(function (q) { return q.id === p.id ? p : q; });
    Store.activeId = p.id; Store.savePlaylists();
    App.home();
  }).catch(function (e) {
    Loader.hide();
