  if (d.toDateString() === n.toDateString()) return '';
  var tm = new Date(n.getFullYear(), n.getMonth(), n.getDate() + 1);
  if (d.toDateString() === tm.toDateString()) return T('tomorrow');
  try { return d.toLocaleDateString(LANG === 'ar' ? 'ar-EG' : 'en-GB', { weekday: 'long' }) + ' ' + d.getDate() + '/' + (d.getMonth() + 1); }
  catch (e) { return d.getDate() + '/' + (d.getMonth() + 1); }
