files.profiles:
/* "Who's watching?": every server (playlist) is a profile, like the profiles of the big streaming apps.
 * OK opens it, green edits it, red deletes it, and the + tile adds a new server (Xtream, M3U link or phone).
 * Plain HTML (a handful of elements). */
'use strict';

var PROFILE_COLORS = [[0xff4ADE80, '#4ADE80'], [0xff38BDF8, '#38BDF8'], [0xffF59E0B, '#F59E0B'], [0xffE5484D, '#E5484D'], [0xffA78BFA, '#A78BFA'], [0xff14B8A6, '#14B8A6'], [0xffF472B6, '#F472B6']];

function profileInitial(name) { var n = String(name || '?').trim(); return (n.charAt(0) || '?').toUpperCase(); }

function ProfileScreen(fromStart) {
  this.fromStart = !!fromStart;
  this.el = U.h('div.screen.profiles');
  this.items = Store.playlists.map(function (p, i) { return { pl: p, i: i }; }).concat([{ add: true }]);
}
/* like the big streaming apps' "Who's watching?": big title, the servers as large rounded pictures in centred
   rows of up to 5, the focused one lifted with a white ring. Plain HTML: a few elements only. */
var PR_PER_ROW = 5, PR_ROW_H = 330, PR_ROWS_SHOWN = 2;
ProfileScreen.prototype.mount = function () {
  var self = this, act = Store.activeId, idx = 0;
  U.clear(this.el);
  this.el.appendChild(U.h('div.pr-glow'));
  this.el.appendChild(U.h('img.pr-logo', { src: 'img/wordmark.png', alt: '' }));
  this.el.appendChild(U.h('div.pr-title', { text: T('whoWatch') }));
  this.el.appendChild(U.h('div.pr-sub', { text: T('prSub').replace('%n', String(this.items.length - 1)) }));
  var view = U.h('div.pr-view' + (this.items.length <= PR_PER_ROW ? '.one' : '')), wrap = U.h('div.pr-wrap');
  view.appendChild(wrap); this.el.appendChild(view); this.wrap = wrap;
  var els = this.items.map(function (x, i) {
    if (x.pl && x.pl.id === act) idx = i;
    var e = ProfileScreen.tile(x, x.pl && x.pl.id === act);
    e._act = function () { self.choose(x); };
    wrap.appendChild(e); return e;
  });
  this.el.appendChild(hint([['ok', T('openSrv')], ['green', T('editPlaylist')], ['red', T('del')]]));
  var fl = this.list = new FList(els, { horizontal: true, scroller: function (e) { self.scrollTo(e); } });
  fl.idx = idx;
};
ProfileScreen.tile = function (x, active) {
  if (x.add) return U.h('div.prof.add', null, U.h('div.pa', null, U.h('span.pplus', { text: '+' })), U.h('div.pn', { text: T('addProfile') }), U.h('div.pt', { text: 'Xtream · M3U · QR' }));
  var c = PROFILE_COLORS[x.i % PROFILE_COLORS.length][1];
  return U.h('div.prof' + (active ? '.on' : ''), null,
    U.h('div.pa', { style: 'background:linear-gradient(145deg,' + c + ' 0%,' + shade(c, 0.55) + ' 100%)' },
      U.h('i.pgloss'), U.h('span.pi', { text: profileInitial(x.pl.name) }), active ? U.h('i.pdot') : null),
    U.h('div.pn', { text: x.pl.name }),
    U.h('div.pt', { text: (x.pl.type === 'xtream' ? 'Xtream' : 'M3U') + (active ? '  ·  ' + T('active') : '') }));
};
function shade(hex, f) {
  var n = parseInt(hex.slice(1), 16), r = Math.round((n >> 16) * f), g = Math.round(((n >> 8) & 255) * f), b = Math.round((n & 255) * f);
  return 'rgb(' + r + ',' + g + ',' + b + ')';
}
/** more than two rows: the rows slide so the focused one is in view */
ProfileScreen.prototype.scrollTo = function (e) {
  var row = Math.round(e.offsetTop / PR_ROW_H), first = this.firstRow || 0;
  if (row < first) first = row; else if (row > first + PR_ROWS_SHOWN - 1) first = row - PR_ROWS_SHOWN + 1;
  this.firstRow = first;
  this.wrap.style.transform = 'translate3d(0,' + (-first * PR_ROW_H) + 'px,0)';
};
ProfileScreen.prototype.choose = function (x) {
  if (x.add) { ProfileScreen.addServer(); return; }
  Store.activeId = x.pl.id; Store.savePlaylists();
  App.profileChosen();
  App.loadActive(false);
};
/** + : how to add the server (Xtream fields, an M3U link, or from the phone). */
ProfileScreen.addServer = function () {
  Modal.pick(T('addHow'), [
    { label: T('xtreamWay'), value: 'xtream' },
    { label: T('m3uWay'), value: 'm3u' },
    { label: T('qrAdd'), value: 'qr' }
  ], function (v) {
    if (!v) return;
    var f = new PlaylistForm(null, false, v === 'm3u' ? 'm3u' : 'xtream');
    App.push(f);
