ProfileScreen.prototype.focusIn = function () { this.list.setActive(true); };
ProfileScreen.prototype.blur = function () { this.list.setActive(false); };
ProfileScreen.prototype.onReturn = function () {
  // a server may have been added, edited or removed
  this.items = Store.playlists.map(function (p, i) { return { pl: p, i: i }; }).concat([{ add: true }]);
  this.mount();
