ProfileScreen.prototype.key = function (k) {
  var self = this, x = this.items[this.list.idx];
  if (k === 'green' && x && x.pl) { App.push(new PlaylistForm(x.pl)); return true; }
  if (k === 'red' && x && x.pl) {
    Modal.confirm(T('confirmDel') + '\n' + x.pl.name, function (y) {
      if (!y) return;
      Store.removePlaylist(x.pl.id);
      if (!Store.playlists.length) { Src.reset(); App.start(); return; }
      self.onReturn(); self.focusIn();
