files.preview:
/* Smart Hub preview: the row of thumbnails shown above the app tile on the TV home bar
 * (top 10 movies, trending series, continue watching), and opening a title when one is clicked there.
 * The foreground app builds the data and hands it to the small background service
 * (service/service.js), which is the only part allowed to call webapis.preview.setPreviewData. */
'use strict';

var SmartHub = (function () {
  var SERVICE = 'IpvioStrm1.service';
  var OP_PICK = 'http://tizen.org/appcontrol/operation/pick';
  var MIN_GAP = 11 * 60000;          // the TV refuses updates closer than 10 minutes
  var MAX_AGE = 6 * 3600000;         // push again at least this often, even if nothing changed
  var pending = null, timer = null, lastErr = '';

  function ls(k, v) {
    try {
      if (v === undefined) return localStorage.getItem(k);
      localStorage.setItem(k, v);
    } catch (e) {}
    return null;
  }

  function cut(s, n) { s = String(s || ''); return s.length > n ? s.substring(0, n - 1) + '…' : s; }

  function tile(title, sub, img, ratio, action) {
    return { title: cut(title, 40), subtitle: cut(sub, 40), image_url: img, image_ratio: ratio, action_data: JSON.stringify(action), is_playable: false };
  }

  /** Builds the preview JSON from what the app already knows (no extra network requests). */
  function build(tm) {
    var sections = [];
    var hist = (Store.history && Store.active() && Store.history[Store.active().id]) || [];
    var cont = [], seen = {};
    hist.forEach(function (h) {
      if (cont.length >= 8 || !h || h.kind === 'live') return;
      var k = h.seriesKey || h.key;
      if (seen[k] || !h.img) return;
      if (h.kind === 'movie' && h.dur && h.pos && h.pos / h.dur > 0.95) return;   // already finished
      seen[k] = 1;
      cont.push(tile(h.seriesName || h.name, h.seriesName ? h.name : '', h.img, '2by3', { key: k }));
    });
    function fromTm(list, n) {
      return TMDB.resolve(list || []).slice(0, n).map(function (e) {
        var sub = [e.rank ? '#' + e.rank : '', e.year || '', e.rating ? '★ ' + (+e.rating).toFixed(1) : ''].filter(Boolean).join('  ·  ');
        // the official poster (with the title on it), like the big streaming apps, not a scene picture
        var poster = e.poster || (e.item && e.item.img);
        return tile(e.title, sub, poster, '2by3', { key: e.item.key });
      }).filter(function (t) { return !!t.image_url; });   // all tiles of a row the same shape
    }
    if (tm) {
      var m = fromTm(tm.trendMovies, 10), s = fromTm(tm.trendSeries, 10);
      if (m.length) sections.push({ title: T('top10'), tiles: m });
      if (s.length) sections.push({ title: T('trendingSeries'), tiles: s });
    }
    if (cont.length) sections.push({ title: T('continueWatching'), tiles: cont });
    if (!sections.length) {
      // no TMDB: newest additions from the playlist
      var fresh = Src.list('movie').filter(function (it) { return it.img; }).slice(0);
      fresh.sort(function (a, b) { return (b.added || 0) - (a.added || 0); });
      var t = fresh.slice(0, 10).map(function (it) { return tile(it.name, it.year || '', it.img, '2by3', { key: it.key }); });
      if (t.length) sections.push({ title: T('newlyAdded'), tiles: t });
    }
    return sections.length ? { sections: sections } : null;
  }

  /** Sends the data to the background service (which sets it and exits). */
  function push(data, force) {
    if (!data) return false;
    var json = JSON.stringify(data);
    var last = +ls('hub_t') || 0, same = ls('hub_h') === String(json.length) + ':' + hash(json);
    var now = Date.now();
    if (!force && same && now - last < MAX_AGE) return false;
    if (now - last < MIN_GAP) { later(MIN_GAP - (now - last) + 2000); return false; }
    if (typeof tizen === 'undefined' || !tizen.application || !tizen.ApplicationControl) return false;
    try {
      var ac = new tizen.ApplicationControl(OP_PICK, null, null, null, [
        new tizen.ApplicationControlData('caller', ['ForegroundApp']),
        new tizen.ApplicationControlData('preview', [json])
      ]);
      var prevT = ls('hub_t'), prevH = ls('hub_h');
      ls('hub_t', String(now)); ls('hub_h', String(json.length) + ':' + hash(json)); lastErr = '';
      tizen.application.launchAppControl(ac, SERVICE, function () {}, function (e) {
        lastErr = (e && (e.name || e.message)) || 'error';
        ls('hub_t', prevT || '0'); ls('hub_h', prevH || '');
      });
      return true;
    } catch (e) { lastErr = e.message || String(e); return false; }
  }

  function hash(s) { var h = 0; for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0; return h; }

  function later(ms) { clearTimeout(timer); timer = setTimeout(function () { update(); }, ms); }

  /** Refreshes the preview from the current TMDB lists (cached; fetched again every few hours). */
  function update(force) {
    if (!Src.data() || (!force && Store.settings.hub === false)) return Promise.resolve(false);
    var p = TMDB.has() ? TMDB.home().catch(function () { return null; }) : Promise.resolve(null);
    return p.then(function (tm) { return push(build(tm), force); });
  }

  /** Keeps the lists and the preview current while the app stays open. */
  function start() {
    clearInterval(start._i);
    // only when the TV is quiet: nothing playing and no key pressed for a while
    function soon() { U.whenQuiet(function () { if (!Player.isActive()) update(); }, 30000, 600000); }
    setTimeout(soon, 60000);
    start._i = setInterval(soon, 60 * 60000);
  }

  /* ---------- opening a title clicked on the home bar ---------- */
  function readPayload() {
    try {
      var r = tizen.application.getCurrentApplication().getRequestedAppControl();
      var d = (r && r.appControl && r.appControl.data) || [];
      for (var i = 0; i < d.length; i++) {
        if (d[i].key !== 'PAYLOAD' || !d[i].value || !d[i].value.length) continue;
        var v = JSON.parse(d[i].value[0]);
        if (v && typeof v.values === 'string') v = JSON.parse(v.values);
        else if (v && v.values && typeof v.values === 'object') v = v.values;
        if (v && v.key) return v;
      }
    } catch (e) {}
    return null;
  }
  function open(a) {
    var it = a && Src.find(a.key);
    if (!it) return false;
    if (Player.isActive()) Player.close();
    if (Trailer.isOpen()) Trailer.close();
    if (Modal.isOpen()) Modal.close();
    App.home();
    Open.item(it);
    return true;
  }
  /** Called once the playlist is loaded. */
  function ready() {
    if (pending) { var a = pending; pending = null; open(a); }
  }
  function init() {
    pending = readPayload();
    window.addEventListener('appcontrol', function () {
      var a = readPayload();
      if (!a) return;
      if (Src.data()) open(a); else pending = a;
    });
  }

  return { init: init, ready: ready, start: start, update: update, build: build, readPayload: readPayload, error: function () { return lastErr; }, _open: open };
})();

files.update:
/* Updates from the TV itself: a newer version (the app's code and look) is downloaded from the update page,
 * kept on the TV, and used from the next start (boot.js). Installing the package again is only needed when the
 * package itself changes (permissions, icon, the Smart Hub service). */
'use strict';

var Updater = (function () {
  var BASE = 'https://mostafaiftc-commits.github.io/mostafa-player-update/';
  var pending = null, timer = null;
  function base() { return String(Store.settings.updateUrl || BASE).replace(/\/*$/, '/'); }
  function idbSet(k, v) {
    return new Promise(function (res, rej) {
      try {
        var r = indexedDB.open('ipvio_ota', 1);
        r.onupgradeneeded = function () { r.result.createObjectStore('kv'); };
        r.onsuccess = function () {
          try {
            var t = r.result.transaction('kv', 'readwrite'); t.objectStore('kv').put(v, k);
            t.oncomplete = function () { res(); }; t.onerror = function () { rej(t.error); }; t.onabort = function () { rej(t.error); };
          } catch (e) { rej(e); }
        };
        r.onerror = function () { rej(r.error); };
      } catch (e) { rej(e); }
    });
  }
  function ls(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
  function setLs(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
  /** manual: from Settings (says what happened) */
  function check(manual) {
    if (manual) Loader.show(T('updChecking'));
    return U.getJson(base() + 'version.json?t=' + Date.now(), 15000).then(function (v) {
      if (!v || !v.version) throw new Error('bad');
      setLs('ota_checked', String(Date.now()));
      if (window.appVersionCmp(v.version, window.APP_VERSION) <= 0 || v.version === ls('ota_bad')) { if (manual) { Loader.hide(); Toast(T('updNone') + '  (v' + window.APP_VERSION + ')'); } return false; }
      if (ls('ota_ver') === v.version) { if (manual) Loader.hide(); ready(v); return true; }    // already downloaded
      return U.getJson(base() + (v.bundle || 'bundle.json') + '?v=' + encodeURIComponent(v.version), 90000).then(function (b) {
        if (!b || b.version !== v.version || !b.files || !b.files.app) throw new Error('bad bundle');
        return idbSet('bundle', b).then(function () {
          setLs('ota_ver', v.version);
          if (manual) Loader.hide();
          ready(v); return true;
        });
      });
    }).catch(function () { if (manual) { Loader.hide(); Toast(T('updFail')); } return false; });
  }
  /** ready to use: asks to restart now (not in the middle of a film; then it is used at the next start) */
  function ready(v) {
    if (Player.isActive() || Trailer.isOpen() || Modal.isOpen()) { pending = v; return; }
    pending = null;
    Modal.confirm(T('updReady').replace('%v', v.version) + (v.notes ? '\n' + v.notes : ''), function (y) { if (y) location.reload(); });
  }
  function start() {
    clearTimeout(timer);
    timer = setTimeout(function () { check(false); }, 30000);
    setInterval(function () { check(false); }, 6 * 3600000);
    setInterval(function () { if (pending && !Player.isActive() && !Modal.isOpen()) ready(pending); }, 20000);
  }
  /** back to the version of the installed package */
  function reset() { try { localStorage.removeItem('ota_ver'); localStorage.removeItem('ota_try'); } catch (e) {} location.reload(); }
  return { start: start, check: check, reset: reset, base: base };
})();

