/* App shell: top navigation bar, screen stack, key dispatch, boot */
'use strict';

var App = (function () {
  var fontsReady = Promise.resolve(), stack = [], sec = null, side = null, sideActive = false, editing = null, editOwner = null, lastBack = 0;
  var SECTIONS = [
    { id: 'search', icon: ICONS.search, label: 'search' },
    { id: 'home', icon: ICONS.home, label: 'home' },
    { id: 'live', icon: ICONS.live, label: 'live' },
    { id: 'movie', icon: ICONS.movie, label: 'movies' },
    { id: 'series', icon: ICONS.series, label: 'series' },
    { id: 'favorites', icon: ICONS.fav, label: 'favorites' },
    { id: 'settings', icon: ICONS.settings, label: 'settings' },
    { id: 'profiles', icon: ICONS.cast, label: 'profiles' }
  ];
  var chosen = false, lastLoaded = null;

  /* ---------- top navigation bar (logo · sections · search · settings · server) ---------- */
  var NAV = [['home', 'navHome'], ['live', 'navLive'], ['movie', 'navMovies'], ['series', 'navSeries'], ['favorites', 'navFav']];
  function buildSidebar() {
    var nb = U.$('#topnav'); U.clear(nb);
    var go = function (id) { return function () { if (id === 'profiles') showProfiles(false); else if (id === sec) setSide(false); else section(id, true); }; };
    var pill = U.h('div.tn-pill'), els = [];
    NAV.forEach(function (s) {
      var e = U.h('div.tn-item', null, U.h('span', { text: T(s[1]) }));
      e._id = s[0]; e._act = go(s[0]); pill.appendChild(e); els.push(e);
    });
    var sr = U.h('div.tn-item.tn-ic', null, U.h('span.ic', { html: ICONS.search }), U.h('span.tn-lb', { text: T('search') }));
    sr._id = 'search'; sr._act = go('search'); pill.appendChild(sr); els.push(sr);
    var pl = Store.active(), pi = Math.max(0, Store.playlists.indexOf(pl));
    var st = U.h('div.tn-round', null, U.h('span.ic', { html: ICONS.settings }));
    st._id = 'settings'; st._act = go('settings');
    var av = U.h('div.tn-av', null,
      U.h('b', { text: profileInitial(pl && pl.name), style: 'background:' + PROFILE_COLORS[pi % PROFILE_COLORS.length][1] }),
      U.h('span.tn-nm', { text: pl ? pl.name : '' }),
      U.h('i.tn-chev', { html: '<svg viewBox="0 0 24 24"><path d="M6 9l6 6 6-6" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>' }));
    av._id = 'profiles'; av._act = go('profiles');
    nb.appendChild(U.h('div.tn-start', null, U.h('img.tn-logo', { src: 'img/wordmark.png', alt: '' })));
    nb.appendChild(pill);
    nb.appendChild(U.h('div.tn-end', null, st, av));
