  function markSection() {
    if (!side) return;
    side.els.forEach(function (e, i) { e.classList.toggle('cur', e._id === sec); if (e._id === sec && !sideActive) side.idx = i; });
  }
  /** The bar shows over the sections themselves, not over pages opened from them, the player or the profiles. */
  function navVis() {
    var show = stack.length === 1 && !!sec && !document.body.classList.contains('no-side');
    document.body.classList.toggle('nav-off', !show);
    return show;
  }
  function setSide(b) {
    if (b && !navVis()) b = false;
    sideActive = b;
    document.body.classList.toggle('side-open', b);
    if (side) side.setActive(b);
    var s = top();
    if (b) { markSection(); if (side) side.draw(); if (s && s.blur) s.blur(); }
    else if (s && s.focusIn) s.focusIn();
