  function mountScreen(s) {
    s.el._screen = s;
    U.$('#main').appendChild(s.el);
    if (s.mount) s.mount();
  }
  function kill(s) {
    if (s.destroy) s.destroy();
    if (s.glRoot && window.GL) { GL.drop(s.glRoot); s.glRoot = null; }
    if (s.el.parentNode) s.el.parentNode.removeChild(s.el);
  }
  function destroyAll() {
    stack.forEach(kill);
    stack = [];
  }

  function create(id) {
    if (id === 'home') return new HomeScreen();
    if (id === 'live') return new LiveScreen();
    if (id === 'movie') return new BrowseScreen('movie');
    if (id === 'series') return new BrowseScreen('series');
    if (id === 'favorites') return new LibraryScreen();
    if (id === 'search') return new SearchScreen();
    return new SettingsScreen();
  }

  function section(id, focusContent) {
    if (!Src.data()) return;
    destroyAll();
    sec = id;
    document.body.classList.remove('no-side');
    var s = create(id);
    if (id !== 'home') s.el.classList.add('with-nav');
    stack.push(s);
    mountScreen(s);
    markSection();
    navVis();
    setSide(false);
    glSync();
    if (id === 'search' && focusContent && s.focusIn) s.focusIn();
