      cur.el.style.display = '';
      if (cur.onReturn) cur.onReturn();
      if (cur.focusIn) cur.focusIn();
    }
  }

  function exitApp() {
    Modal.confirm(T('exitQ'), function (y) {
      if (!y) return;
      Engine.stop();
      try { tizen.application.getCurrentApplication().exit(); } catch (e) { window.close(); }
    });
  }

  function back() {
    if (stack.length > 1) { pop(); return; }
    if (stack[0] instanceof ProfileScreen) { if (Src.data() && Store.active()) { document.body.classList.remove('no-side'); section('home'); } else exitApp(); return; }
    if (!Store.playlists.length) { exitApp(); return; }
    if (!sideActive && top() && top().onBack && top().onBack()) return;
    if (!sideActive) { setSide(true); return; }
    if (sec !== 'home') { section('home'); setSide(true); return; }
