    if (lastLoaded !== pl.id) { lastLoaded = pl.id; Sports.reset(); }   // channel ids and guides belong to one server
    document.body.classList.remove('no-side');
    Loader.show(T('loadingList'));
    Src.load(pl, function (t) { Loader.text(t); }, force).then(function () { return fontsReady; }).then(function () {
      Loader.text(T('prepUi'));
      return Warmup.run(function (pct) { Loader.text(T('prepUi') + '  ' + pct + '%'); });
    }).then(function () {
      Loader.hide();
      buildSidebar();
      home();
      MatchWatch.start();
      NewEps.start();
      SmartHub.start();
      SmartHub.ready();
      if (cb) cb();
    }).catch(function (e) {
      Loader.hide();
      var many = Store.playlists.length > 1;
      Modal.pick(pl.name + ': ' + (e.message || T('errNet')), (many ? [{ label: T('backSrv'), value: 'profiles' }] : []).concat([
        { label: T('refresh'), value: 'retry' },
        { label: T('editPlaylist'), value: 'edit' },
        { label: T('addPlaylist'), value: 'add' }
      ]), function (v) {
        if (v === 'profiles' || (!v && many)) { showProfiles(false); }
        else if (v === 'edit') { showForm(pl); }
        else if (v === 'add') { showForm(null); }
        else loadActive(true, cb);
      });
    });
  }

  function showForm(pl) {
    destroyAll();
    document.body.classList.add('no-side'); navVis();
    var f = new PlaylistForm(pl, true);
    stack.push(f); mountScreen(f); f.focusIn();
  }

  /** "Who's watching?" (one profile per server). */
  function showProfiles(fromStart) {
    destroyAll();
    sec = null; markSection();
    sideActive = false; document.body.classList.remove('side-open'); if (side) side.setActive(false);
    document.body.classList.add('no-side'); navVis();
    var p = new ProfileScreen(fromStart);
    stack.push(p); mountScreen(p); glSync(); p.focusIn();
  }
  function start() {
    destroyAll();
    if (!Store.playlists.length) { showForm(null); return; }
    if (Store.playlists.length > 1 && !chosen) { showProfiles(true); return; }
    loadActive(false);
  }

  function rebuild() {
    buildSidebar();
    if (Src.data()) { section('settings'); setSide(false); }
    else start();
  }

  /* ---------- text input with the TV keyboard ---------- */
  function editInput(inp, owner) {
    editing = inp; editOwner = owner;
