    if (!inp) return;
    inp.parentNode.classList.remove('editing');
    inp.blur();
    if (done && owner && owner.onInputDone) owner.onInputDone();
  }

  function onKey(ev) {
    var code = ev.keyCode;
    if (editing) {
      if (code === 65376 || code === 13) { ev.preventDefault(); endEdit(true); return; }
      if (code === 65385 || code === 10009 || code === 27) { ev.preventDefault(); endEdit(false); return; }
      if (code === 38 || code === 40) { endEdit(false); }
      else return; // typing, cursor keys
    }
    U.lastKey = Date.now();
    var name = Keys.CODES[code];
    if (!name) return;
    if (code === 8 && document.activeElement && document.activeElement.tagName === 'INPUT') return;
    ev.preventDefault();
    if (Loader.visible()) return;
    if (Trailer.isOpen()) { Trailer.key(name); return; }
    if (PhoneLink.isOpen()) { PhoneLink.key(name); return; }
    if (Modal.isOpen()) { Modal.key(Keys.logical(name, true)); return; }
    if (MatchWatch.key(name)) return;
    if (Player.isActive()) { Player.key(name); return; }
    var k = Keys.logical(name);
    if (k === 'back') { back(); return; }
    if (k === 'exit') { exitApp(); return; }
    var s = top();
