// the files are added one by one by boot.js: the page may have finished loading already
if (document.readyState === 'complete') App.init(); else window.addEventListener('load', function () { App.init(); });

css:
/* Mostafa Player for Tizen (based on IPVIO Stream) - 1920x1080 canvas */
@font-face { font-family: 'Outfit'; src: url('fonts/outfit_regular.ttf') format('truetype'); font-weight: 400; }
@font-face { font-family: 'Outfit'; src: url('fonts/outfit_bold.ttf') format('truetype'); font-weight: 700; }
@font-face { font-family: 'CairoAr'; src: url('fonts/cairo-ar-400.woff2') format('woff2'); font-weight: 400; unicode-range: U+0600-06FF, U+0750-077F, U+FB50-FDFF, U+FE70-FEFF, U+200C-200F; }
@font-face { font-family: 'CairoAr'; src: url('fonts/cairo-ar-700.woff2') format('woff2'); font-weight: 700; unicode-range: U+0600-06FF, U+0750-077F, U+FB50-FDFF, U+FE70-FEFF, U+200C-200F; }

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { width: 1920px; height: 1080px; overflow: hidden; color: #F4F6FB;
  font-family: 'Outfit', 'CairoAr', 'SamsungOne', sans-serif; font-size: 26px; -webkit-font-smoothing: antialiased; }
html { background: transparent; }
body { background: #0B0F19; }
svg { width: 100%; height: 100%; fill: currentColor; }

#avplayer { position: fixed; left: 0; top: 0; width: 1920px; height: 1080px; z-index: 0; }
#h5video { position: fixed; left: 0; top: 0; width: 100vw; height: 100vh; display: none; background: #000; z-index: 0; object-fit: contain; }
#app { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; transform-origin: 0 0; z-index: 1; overflow: hidden; }

body.playing, body.playing #app { background: transparent; }
body.playing #sidebar, body.playing #main { visibility: hidden; }

/* ---------- images ---------- */
.pimg, .lg, .wimg, .bgi, .eimg, .d-poster { position: relative; overflow: hidden; background: #1F2739; }
.pimg img, .lg img, .wimg img, .bgi img, .eimg img, .d-poster img { position: absolute; left: 0; top: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity .25s; }
.ok > img { opacity: 1; }
.ok > .ph { display: none; }
.ph { position: absolute; left: 0; right: 0; top: 50%; transform: translateY(-50%); text-align: center; padding: 0 14px; color: #A0A6B8; font-weight: 700; font-size: 24px; line-height: 1.25; overflow: hidden; max-height: 100%; }
.lg { background: #F4F6FB; border-radius: 14px; }
.lg:not(.ok) { background: #2A3347; }
.lg img { object-fit: contain; padding: 8px; }
.lg .ph { color: #F4F6FB; font-size: 22px; }

.prog { height: 6px; background: rgba(255,255,255,.18); border-radius: 3px; overflow: hidden; }
.prog > div { height: 100%; background: #4ADE80; border-radius: 3px; }
.eprog { height: 5px; background: rgba(255,255,255,.15); border-radius: 3px; overflow: hidden; }
.eprog > div { height: 100%; background: #4ADE80; }
.empty { padding: 60px 20px; color: #A0A6B8; font-size: 30px; }
.dim { color: #A0A6B8; }
.badge { display: inline-block; background: #E5484D; color: #fff; font-weight: 700; font-size: 20px; letter-spacing: 2px; padding: 4px 14px; border-radius: 8px; }
.kicker { color: #4ADE80; font-weight: 700; letter-spacing: 6px; font-size: 26px; text-transform: uppercase; padding-left: 18px; border-left: 6px solid #4ADE80; }
[dir=rtl] .kicker { border-left: 0; border-right: 6px solid #4ADE80; padding-left: 0; padding-right: 18px; letter-spacing: 0; }
.favm { display: inline-block; width: 26px; height: 26px; color: #FF6B6B; vertical-align: middle; margin: 0 8px; }

/* ---------- sidebar ---------- */
#sidebar { position: absolute; top: 0; left: 0; width: 110px; height: 1080px; background: #0B0F19; z-index: 20; padding-top: 30px; overflow: hidden; transition: width .22s cubic-bezier(.2,.8,.2,1); box-shadow: 0 0 0 1px rgba(255,255,255,.04); }
[dir=rtl] #sidebar { left: auto; right: 0; }
body.side-open #sidebar { width: 330px; box-shadow: 30px 0 80px rgba(0,0,0,.6); }
[dir=rtl] body.side-open #sidebar { box-shadow: -30px 0 80px rgba(0,0,0,.6); }
body.no-side #sidebar { display: none; }
.sb-logo { display: flex; align-items: center; height: 80px; padding: 0 23px; margin-bottom: 40px; white-space: nowrap; }
.sb-logo img { width: 64px; height: 64px; flex: none; }
.sb-logo span { font-weight: 700; font-size: 34px; margin: 0 18px; opacity: 0; transition: opacity .18s; }
body.side-open .sb-logo span { opacity: 1; }
.sb-item { display: flex; align-items: center; height: 76px; margin: 8px 18px; padding: 0 19px; border-radius: 18px; color: #A0A6B8; white-space: nowrap; }
.sb-item .ic { width: 36px; height: 36px; flex: none; }
.sb-item .lb { margin: 0 22px; font-size: 28px; font-weight: 700; opacity: 0; transition: opacity .18s; }
body.side-open .sb-item .lb { opacity: 1; }
.sb-item.cur { color: #4ADE80; background: rgba(74,222,128,.12); }
.sb-item.focus { background: #4ADE80; color: #0B0F19; }

/* ---------- main ---------- */
#main { position: absolute; top: 0; left: 110px; right: 0; height: 1080px; }
[dir=rtl] #main { left: 0; right: 110px; }
body.no-side #main { left: 0; right: 0; }
.screen { position: absolute; left: 0; top: 0; width: 100%; height: 100%; overflow: hidden; }

.vlist, .vgrid, .hbox { position: relative; overflow: hidden; }
.vinner { position: absolute; left: 0; right: 0; top: 0; transition: transform .16s ease-out; }
.vinner > .vrow { position: absolute; left: 0; right: 0; }
.vinner > .vcell { position: absolute; }
.hinner { display: flex; transition: transform .2s ease-out; padding: 14px 0; }
.hinner > * { flex: none; margin-inline-end: 24px; }
[dir=rtl] .hinner > * { margin-left: 24px; margin-right: 0; }
.hinner > * { margin-right: 24px; }

/* buttons */
.btn { display: inline-flex; align-items: center; height: 72px; padding: 0 38px; border-radius: 40px; background: rgba(255,255,255,.12); color: #F4F6FB; font-weight: 700; font-size: 28px; margin-inline-end: 18px; border: 2px solid rgba(255,255,255,.18); transition: transform .12s; }
.btn { margin-right: 18px; }
[dir=rtl] .btn { margin-right: 0; margin-left: 18px; }
.btn .ic { width: 30px; height: 30px; margin: 0 14px 0 0; }
[dir=rtl] .btn .ic { margin: 0 0 0 14px; }
.btn.primary { background: rgba(255,255,255,.9); color: #0B0F19; }
.btn.on .ic { color: #FF6B6B; }
.btn.focus { background: #4ADE80; color: #0B0F19; border-color: #86EFAC; transform: scale(1.06); box-shadow: 0 8px 30px rgba(74,222,128,.35); }

/* cards */
.card { border-radius: 18px; transition: transform .14s, box-shadow .14s; position: relative; }
.card.focus { transform: scale(1.07); z-index: 2; }
.card.poster .pimg { width: 100%; height: 300px; border-radius: 16px; border: 3px solid transparent; }
.card.poster.focus .pimg { border-color: #4ADE80; box-shadow: 0 10px 40px rgba(74,222,128,.35); }
.card.poster .ct { margin-top: 12px; font-size: 23px; line-height: 1.3; max-height: 60px; overflow: hidden; color: #D3D7E2; text-align: center; }
.card.poster.focus .ct { color: #fff; }
.card .rate { position: absolute; top: 10px; left: 10px; background: rgba(11,15,25,.85); color: #FFD166; font-weight: 700; font-size: 20px; padding: 3px 10px; border-radius: 8px; }
[dir=rtl] .card .rate { left: auto; right: 10px; }
.card.poster .favm { position: absolute; top: 10px; right: 6px; }
[dir=rtl] .card.poster .favm { right: auto; left: 6px; }
.card.poster .cs { text-align: center; color: #4ADE80; font-size: 20px; }
.card.poster .prog { margin: 6px 16px 0; }
.hrow-wrap.posters .card.poster { width: 200px; }
.vcell.card.poster .pimg { height: calc(100% - 76px); }

.card.chan { width: 320px; height: 190px; background: #151B2A; border: 3px solid rgba(255,255,255,.08); padding: 18px; display: flex; flex-direction: column; align-items: center; }
.card.chan .lg { width: 96px; height: 64px; border-radius: 10px; flex: none; }
.card.chan .ct { margin-top: 12px; font-weight: 700; font-size: 24px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.card.chan .cs { margin-top: 6px; font-size: 20px; color: #A0A6B8; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.ldot { display: inline-block; width: 10px; height: 10px; border-radius: 5px; background: #4ADE80; margin: 0 8px; }
.card.chan.focus { border-color: #4ADE80; background: #1F2739; }
.vcell.card.chan { padding-top: 40px; }
.vcell.card.chan .lg { width: 150px; height: 100px; }

.card.wide { width: 380px; }
.card.wide .wimg { width: 380px; height: 214px; border-radius: 16px; border: 3px solid transparent; }
.card.wide.focus .wimg { border-color: #4ADE80; }
.card.wide .ct { margin-top: 10px; font-weight: 700; font-size: 24px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.card.wide .cs { font-size: 20px; color: #A0A6B8; }
.card.wide .prog { position: absolute; left: 14px; right: 14px; top: 196px; }

.card.tile { width: 324px; height: 120px; border-radius: 22px; display: flex; align-items: center; padding: 0 26px; border: 3px solid rgba(255,255,255,.1); }
.card.tile .ic { width: 50px; height: 50px; flex: none; }
.card.tile .tx { margin: 0 20px; }
.card.tile b { display: block; font-size: 30px; }
.card.tile span { font-size: 21px; opacity: .85; }
.t-live { background: linear-gradient(120deg, #7C4A12, #3A2410); color: #FFD9A6; }
.t-movie { background: linear-gradient(120deg, #1E3A8A, #172554); color: #BFD7FF; }
.t-series { background: linear-gradient(120deg, #5B21B6, #2E1065); color: #E2D5FF; }
.t-fav { background: linear-gradient(120deg, #9F1239, #4C0519); color: #FFD3DC; }
.t-search { background: linear-gradient(120deg, #0F766E, #134E4A); color: #C7FFF4; }
.card.tile.focus { border-color: #4ADE80; box-shadow: 0 10px 40px rgba(74,222,128,.3); }

/* category rows */
.col { position: absolute; top: 0; height: 1080px; }
.catrow { display: flex; align-items: center; padding: 0 26px; border-radius: 16px; color: #A0A6B8; font-size: 26px; }
.catrow .cn { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.catrow .cc { font-size: 21px; opacity: .8; margin: 0 0 0 12px; }
.vrow.sel .catrow, .catrow.sel { color: #4ADE80; }
.vrow.sel.catrow { color: #4ADE80; }
.vlist .vrow.catrow.sel { color: #4ADE80; background: rgba(74,222,128,.08); }
.vlist .vrow.catrow.focus { background: #4ADE80; color: #0B0F19; }
.vlist:not(.active) .vrow.catrow.sel { background: rgba(255,255,255,.06); }

/* hint bar */
.hint { position: absolute; bottom: 18px; right: 40px; font-size: 21px; color: #A0A6B8; }
