/* =====================================================================
   Motion tuned for the TV's GPU: every animation moves only transform or
   opacity, so the browser composites it instead of repainting the screen.
   ===================================================================== */
/* sidebar: the big soft shadow is painted once and only fades */
body.side-open #sidebar, [dir=rtl] body.side-open #sidebar { box-shadow: none; }
#app:after { content: ''; position: absolute; top: 0; bottom: 0; left: 0; width: 700px; z-index: 19; pointer-events: none;
  background: linear-gradient(90deg, rgba(0,0,0,.75), rgba(0,0,0,0)); opacity: 0; transition: opacity .25s; }
[dir=rtl] #app:after { left: auto; right: 0; background: linear-gradient(270deg, rgba(0,0,0,.75), rgba(0,0,0,0)); }
body.side-open #app:after { opacity: 1; }

/* hero: crossfading layers and Ken Burns on their own GPU layers */
.hb-layer { will-change: opacity; transition: opacity 1s cubic-bezier(.4,0,.2,1); }
.hb-layer img { will-change: transform; }
#yt { will-change: opacity; }
.hi { transition: opacity .11s ease; top: 120px !important; }
.hi.fade { opacity: 0; }
.home.in-rows .hi { transform: translate3d(0, -60px, 0); }
.hi-title { transition: none; text-shadow: 0 4px 24px rgba(0,0,0,.5); }
.home .rows { top: 500px !important; transform: translate3d(0, 300px, 0); transition: transform .28s cubic-bezier(.2,.8,.2,1); will-change: transform; }
.home.in-rows .rows { transform: translate3d(0, 0, 0); }
.rows-inner { transition: transform .24s cubic-bezier(.2,.8,.2,1); }
.hinner { transition: transform .18s cubic-bezier(.2,.8,.2,1); }
.vinner { transition: transform .15s cubic-bezier(.2,.8,.2,1); }
#toast { transition: opacity .2s, transform .2s; }

/* series page: lists slide with transform instead of moving "top" */
.seriesd .s-low { top: 300px !important; transform: translate3d(0, 260px, 0); transition: transform .3s cubic-bezier(.2,.8,.2,1); }
.seriesd.in-eps .s-low { transform: translate3d(0, 0, 0); }

/* focus glow: a pre-painted shadow behind the card that only fades in */
.card, .btn { isolation: isolate; }
.card { transition: transform .13s cubic-bezier(.2,.8,.2,1); }
.card:before, .btn:before { content: ''; position: absolute; left: 0; right: 0; top: 0; bottom: 0; border-radius: inherit; z-index: -1; pointer-events: none;
  box-shadow: 0 12px 44px rgba(74,222,128,.42); opacity: 0; transition: opacity .15s ease; }
.card.focus:before, .btn.focus:before { opacity: 1; }
.btn { position: relative; }
.btn.focus { box-shadow: none; }
.card.poster:before { bottom: auto; height: 300px; border-radius: 16px; }
.vcell.card.poster:before { height: calc(100% - 76px); }
.card.rank:before { left: auto; width: 200px; bottom: auto; height: 300px; border-radius: 16px; }
[dir=rtl] .card.rank:before { left: 0; right: auto; }
.card.wide:before { bottom: auto; height: 214px; border-radius: 16px; }
.card.land { overflow: visible; }
.card.land .wimg { border-radius: 16px; overflow: hidden; }
.card.land .lgrad { border-radius: 0 0 16px 16px; }
.card.chan:before, .card.tile:before, .card.promo:before { border-radius: 22px; }
.card.poster.focus .pimg, .card.tile.focus, .card.rank.focus .pimg, .card.land.focus { box-shadow: none; }

/* sort button in movie/series lists */
.bhead { align-items: center; }
.bhead .bt { max-width: 640px; }
.btn.sortbtn { margin: 0 0 0 auto; height: 62px; padding: 0 26px; font-size: 24px; flex: none; }
