.btn.sortbtn .ic { width: 28px; height: 28px; }
.hint { background: rgba(11,15,25,.9); border-radius: 14px; padding: 8px 10px; z-index: 5; }

/* very wide/tall scrolling strips must not become permanent GPU layers (memory on the TV) */
.vinner, .hinner, .rows-inner { will-change: auto; }
/* Top 10 numbers: 10 is two digits, keep it inside its space */
.card.rank .rk.two { letter-spacing: -6px; transform: scaleX(.6); transform-origin: left bottom; }
[dir=rtl] .card.rank .rk.two { transform-origin: right bottom; }
/* brand */
