/* =====================================================================
   Smoothness pass (v1.19): on the TV the GPU and the CPU raster are slow, so
   - nothing animates forever (no Ken Burns zoom, no pulsing dots): when nothing moves, nothing is drawn;
   - focus = border + scale only: no blurred glows (a 40px blur costs more than the whole card);
   - the strips that slide keep their own layer, so sliding them is a cheap move and not a repaint;
   - the hero text fades as one block instead of four moving pieces.
   ===================================================================== */
.hb-layer { transition: opacity .45s ease; }
.hb-layer img, .hb-layer.on img { animation: none !important; will-change: auto; transform: none; }
.home .hb-layer { transition: opacity .45s ease; }
.card:before, .btn:before { display: none !important; }
.card, .btn { isolation: auto; }
.card.poster.focus .pimg, .card.rank.focus .pimg { border-color: #4ADE80; box-shadow: none; }
.card.tile.focus, .card.land.focus, .btn.focus { box-shadow: none; }
.card { transition: transform .12s ease-out; }
.btn { transition: none; }
.home .rows-inner { will-change: transform; }
.hrow.active .hinner { will-change: transform; }
.vlist.active .vinner, .vgrid.active .vinner { will-change: transform; }
.hinner img, .vinner img, .rows-inner img { transition: none !important; }
.hi.swap > * { animation: none !important; }
.hi.swap { animation: hfade .3s ease both; }
@keyframes hfade { from { opacity: 0; } to { opacity: 1; } }
.hi-title, .home.in-rows .hi-title { text-shadow: 0 2px 4px rgba(0,0,0,.55); transition: none; }
.hi-dots span { transition: none; }
.hb-layer.poster img { box-shadow: none; }
.m-live i, .scb-live i, .md-st.live i, .ph-status:before { animation: none !important; }
#sidebar { transition: none; }
#app:after { transition: none; }
.sb-logo span, .sb-item .lb { transition: opacity .12s; }
.seriesd .s-low, .home .rows { transition-duration: .22s; }
#app:after { display: none; }
body.side-open #app:after { display: block; }

/* ---------- fast engine (gl.js): the WebGL canvas sits under the HTML screens ---------- */
#gl { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; z-index: 2; pointer-events: none; }
#main { z-index: 3; }
.home.gl .hb, .home.gl .rows { display: none; }
