/* The white dot: the TV's video window (<object type=application/avplayer>) sat full screen under the whole
   app and showed through every see-through layer (it was dimmed inside the loading screen). Now it only
   exists while a video plays, and the app paints its own background above it the rest of the time. */
#avplayer { display: none; }
body:not(.playing) #app { background: #0B0F19; }

