.cert.c16 { border-color: #F59E0B; color: #FCD34D; }
.cert.c18 { border-color: #F87171; color: #fff; background: #DC2626; }
.hi-adv, .d-adv { margin-top: 10px; font-size: 22px; font-weight: 600; color: #C9CEDA; }
.hi-adv:empty, .d-adv:empty { display: none; }
.home.in-rows .hi-adv { display: none; }
/* round pictures: a scene with the title picture on it */
.hs-in { position: absolute; left: 0; top: 0; width: 100%; height: 100%; border-radius: 50%; overflow: hidden; border: 3px solid rgba(255,255,255,.22); background: #1A2030; }
.hs-in .hs-img { position: absolute; left: 0; top: 0; width: 100%; height: 100%; border: 0; border-radius: 0; }
.hs-shade { position: absolute; left: 0; right: 0; bottom: 0; height: 70%; background: linear-gradient(0deg, rgba(0,0,0,.85), rgba(0,0,0,0)); }
.hs-logo { position: absolute; left: 10%; width: 80%; bottom: 12%; height: 40%; object-fit: contain; filter: drop-shadow(0 1px 3px rgba(0,0,0,.9)); }
.hs-name { position: absolute; left: 8%; right: 8%; bottom: 16%; font-size: 13px; line-height: 1.15; font-weight: 700; color: #fff; text-align: center; max-height: 31px; overflow: hidden; text-shadow: 0 1px 3px #000; }
.hs-it.cur .hs-in { border-color: rgba(255,255,255,.12); }
.hs-it, .hs-in { width: 96px; height: 96px; }
.hs-ring { left: -9px; top: -9px; width: 114px; height: 114px; }
.hs-it.cur { transform: scale(1.32); margin: 0 28px; }
/* the home without the fast engine: rows wait below the hero like the drawn ones */
.home .rows { top: 470px !important; transform: translate3d(0, 514px, 0); }
.home.in-rows .rows { transform: translate3d(0, 0, 0); }
.d-brand.wait { visibility: hidden; }
.d-meta .cert { font-size: 21px; }
/* age rating over the video for a few seconds at the start */
#pcert { position: absolute; top: 76px; left: 84px; z-index: 31; display: flex; align-items: stretch; opacity: 0; transform: translate3d(-24px, 0, 0);
  transition: opacity .45s ease, transform .45s ease; pointer-events: none; }
[dir=rtl] #pcert { left: auto; right: 84px; transform: translate3d(24px, 0, 0); }
#pcert.on, [dir=rtl] #pcert.on { opacity: 1; transform: none; }
body:not(.playing) #pcert { display: none; }
#pcert .pc-bar { width: 6px; border-radius: 3px; background: #4ADE80; flex: none; }
#pcert.c13 .pc-bar { background: #FACC15; } #pcert.c16 .pc-bar { background: #F59E0B; } #pcert.c18 .pc-bar { background: #E5484D; }
#pcert .pc-tx { margin: 0 18px; display: flex; flex-direction: column; justify-content: center; text-shadow: 0 2px 10px rgba(0,0,0,.85); }
#pcert b { font-size: 46px; font-weight: 700; line-height: 1.1; color: #fff; direction: ltr; unicode-bidi: isolate; }
[dir=rtl] #pcert b { text-align: right; }
#pcert span { font-size: 26px; font-weight: 600; color: #E6E9F1; margin-top: 4px; }
.hi.warming + .hstrip { opacity: 0; }
#pcert { padding: 14px 20px; border-radius: 12px; background: rgba(0,0,0,.42); }
.home .rows-inner { padding: 0 110px; } .home .hrow-wrap .hbox { margin: 0 -110px; padding: 0 110px; }
/* the preview fills the screen while the remote rests */
.home .rows, .home .hstrip, .home .hb-grad { transition: opacity .9s ease; }
.home.immersive .rows { opacity: .16; }
.home.immersive .hstrip { opacity: .25; }
.home.immersive .hb-grad { opacity: .45; }
.home.immersive .hi-meta, .home.immersive .hi-kick, .home.immersive .hi-adv { opacity: .7; transition: opacity .9s; }
/* movie page: the poster stays beside the text, over the wide picture */
.detail.has-bd .d-poster, .detail .d-poster { display: block; width: 380px; height: 570px; border-radius: 22px; align-self: center;
  box-shadow: 0 30px 80px rgba(0,0,0,.65), 0 0 0 1px rgba(255,255,255,.14); }
.detail .d-body { top: 150px; bottom: 110px; align-items: center; }
.detail .d-txt { max-width: 1140px; }
.detail .d-bg .bgi { position: absolute; left: 0; top: 0; }
.detail .d-bg .bgi.pbg img { opacity: .35 !important; }
body.home-imm #topnav { opacity: .12; }

/* skip intro / recap: a glass button whose fill shows the seconds left (like the big streaming apps) */
#pskip { right: 84px; bottom: 140px; padding: 0; height: 76px; min-width: 300px; border-radius: 16px; overflow: hidden; color: #fff;
  background: linear-gradient(180deg, rgba(40,46,64,.82), rgba(14,18,30,.82)); border: 2px solid rgba(255,255,255,.7);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.25), 0 14px 40px rgba(0,0,0,.55); -webkit-mask-image: -webkit-radial-gradient(white, black); }
[dir=rtl] #pskip { right: auto; left: 84px; }
body.playing #pskip.show { display: flex; align-items: center; justify-content: center; }
#pskip .sk-fill { position: absolute; left: 0; top: 0; width: 100%; height: 100%; background: linear-gradient(180deg, rgba(255,255,255,.34), rgba(255,255,255,.2));
  transform-origin: left center; transform: scaleX(0); }
[dir=rtl] #pskip .sk-fill { transform-origin: right center; }
#pskip .sk-fill.run { transform: scaleX(1); transition: transform 6s linear; }
#pskip .sk-ic { position: relative; width: 30px; height: 30px; margin: 0 0 0 34px; flex: none; }
[dir=rtl] #pskip .sk-ic { margin: 0 34px 0 0; transform: scaleX(-1); }
#pskip .sk-tx { position: relative; font-size: 28px; font-weight: 700; margin: 0 34px 0 14px; white-space: nowrap; text-shadow: 0 1px 4px rgba(0,0,0,.5); }
[dir=rtl] #pskip .sk-tx { margin: 0 14px 0 34px; }
#player-ui.osd ~ #pskip { bottom: 300px; }

/* =====================================================================
   glass look (like the phones): see-through layers with a light edge on top. The TV's browser has no blur,
   so the glass is drawn with gradients and a thin highlight only (nothing for the TV to compute per frame).
   ===================================================================== */
.tn-pill, .tn-round, .tn-av, .hb-round, .detail .d-btns .btn:not(.primary):not(.focus), .seriesd .d-btns .btn:not(.primary):not(.focus),
.p-btn:not(.focus), .search .skb, .stab:not(.focus), .hint, #pcert {
  background: linear-gradient(180deg, rgba(255,255,255,.16) 0%, rgba(255,255,255,.06) 55%, rgba(255,255,255,.08) 100%);
  border: 1px solid rgba(255,255,255,.2);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.28), inset 0 -1px 0 rgba(0,0,0,.25), 0 10px 30px rgba(0,0,0,.3);
}
.tn-pill { background: linear-gradient(180deg, rgba(40,46,64,.62), rgba(14,18,30,.62)); }
.tn-item.cur { background: linear-gradient(180deg, rgba(255,255,255,.26), rgba(255,255,255,.12)); box-shadow: inset 0 1px 0 rgba(255,255,255,.35); }
.tn-item.focus, .tn-round.focus, .tn-av.focus, .hb-round.focus { box-shadow: 0 8px 28px rgba(0,0,0,.45), 0 0 0 4px rgba(255,255,255,.16); }
.mbox { background: linear-gradient(180deg, rgba(36,42,60,.94), rgba(16,20,32,.96)); border: 1px solid rgba(255,255,255,.18);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.22), 0 40px 100px rgba(0,0,0,.7); border-radius: 34px; }
#modal { background: rgba(4,6,12,.62); }
#toast { background: linear-gradient(180deg, rgba(48,54,74,.95), rgba(20,24,38,.95)); color: #fff; border: 1px solid rgba(255,255,255,.22);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.25), 0 16px 40px rgba(0,0,0,.5); }
.set-row { background: linear-gradient(180deg, rgba(255,255,255,.07), rgba(255,255,255,.03)); border: 1px solid rgba(255,255,255,.08); box-shadow: inset 0 1px 0 rgba(255,255,255,.08); }
.set-row.focus { background: linear-gradient(180deg, rgba(74,222,128,.22), rgba(74,222,128,.08)); border-color: #4ADE80; }
.search .sk { background: linear-gradient(180deg, rgba(255,255,255,.1), rgba(255,255,255,.04)); box-shadow: inset 0 1px 0 rgba(255,255,255,.12); }
.search .sk.focus { background: #fff; }
.hb-watch, .detail .d-btns .btn.primary, .seriesd .d-btns .btn.primary { background: linear-gradient(180deg, #FFFFFF, #E4E8F0); box-shadow: inset 0 -2px 0 rgba(0,0,0,.08), 0 12px 30px rgba(0,0,0,.35); }
.hb-watch.focus, .detail .d-btns .btn.primary.focus, .seriesd .d-btns .btn.primary.focus { background: linear-gradient(180deg, #6EE7A0, #34C46E); }
.p-top, .p-bottom { -webkit-font-smoothing: antialiased; }
.hint { padding: 8px 14px; border-radius: 16px; }

/* =====================================================================
   player: quiet and clear. A soft shade at the top and bottom only, a thin progress line, round icon
   buttons for play / seek and plain text ones for the rest (no boxes until a button has the focus).
   ===================================================================== */
.p-top { height: 260px; padding: 56px 84px 0; background: linear-gradient(180deg, rgba(0,0,0,.72) 0%, rgba(0,0,0,.35) 55%, rgba(0,0,0,0) 100%); align-items: flex-start; }
.p-title { font-size: 42px; letter-spacing: .2px; text-shadow: 0 2px 12px rgba(0,0,0,.6); }
.p-sub { font-size: 25px; color: #C9CEDA; margin-top: 8px; }
.p-clock { font-size: 32px; font-weight: 600; color: #E6E9F1; }
.p-logo .lg { width: 104px; height: 70px; border-radius: 12px; margin-right: 24px; }
.p-bottom { padding: 160px 84px 46px; background: linear-gradient(0deg, rgba(0,0,0,.85) 0%, rgba(0,0,0,.55) 45%, rgba(0,0,0,0) 100%); }
.p-bar { margin-bottom: 26px; font-size: 22px; color: #D9DCE4; font-weight: 600; }
.p-track { height: 6px; border-radius: 3px; background: rgba(255,255,255,.22); margin: 0 22px; transition: height .15s; }
.p-fill { border-radius: 3px; background: linear-gradient(90deg, #34D399, #4ADE80); }
.p-knob { top: -8px; width: 22px; height: 22px; margin-left: -11px; border-radius: 11px; background: #fff; box-shadow: 0 0 0 5px rgba(74,222,128,.35), 0 2px 8px rgba(0,0,0,.5); }
.p-btns { display: flex; align-items: center; justify-content: space-between; }
.p-bl, .p-br { display: flex; align-items: center; }
.p-btn, .p-btn:not(.focus) { background: transparent; border: 0; box-shadow: none; height: 64px; padding: 0 22px; margin: 0 6px 0 0; border-radius: 32px;
  color: #D9DCE4; font-size: 24px; font-weight: 600; transition: transform .12s ease-out; }
.p-btn .ic { width: 30px; height: 30px; }
.p-btn .lb { margin-left: 12px; white-space: nowrap; }
.p-btn.round, .p-btn.round:not(.focus) { width: 64px; padding: 0; justify-content: center; border-radius: 32px; border: 2px solid rgba(255,255,255,.35); margin-right: 18px; }
.p-btn.round.big, .p-btn.round.big:not(.focus) { width: 78px; height: 78px; border-radius: 39px; border-color: rgba(255,255,255,.6); }
.p-btn.round.big .ic { width: 36px; height: 36px; }
.p-btn.round.on .ic { color: #FF6B6B; }
.p-btn.pill, .p-btn.pill:not(.focus) { border: 2px solid rgba(255,255,255,.35); margin-right: 18px; }
.p-btn.focus { background: #fff; color: #07090F; border-color: #fff; transform: scale(1.08); box-shadow: 0 8px 26px rgba(0,0,0,.5); }
.p-br .p-btn { margin: 0 0 0 8px; }
#player-ui.osd .p-track { height: 8px; }
.p-next { right: 84px; bottom: 250px; width: 520px; border: 0; border-radius: 22px; background: linear-gradient(180deg, rgba(40,46,64,.92), rgba(14,18,30,.94));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.2), 0 20px 50px rgba(0,0,0,.55); }

/* age rating, like the big streaming apps: | +18 big, contents small below */
.certb { display: inline-flex; align-items: stretch; text-shadow: 0 2px 10px rgba(0,0,0,.6); }
.certb .cb-bar { width: 5px; border-radius: 3px; flex: none; background: #4ADE80; }
.certb.c13 .cb-bar { background: #FACC15; } .certb.c16 .cb-bar { background: #F59E0B; } .certb.c18 .cb-bar { background: #E5484D; }
.certb .cb-tx { display: flex; flex-direction: column; justify-content: center; padding: 2px 16px; }
.certb b { font-size: 38px; font-weight: 700; line-height: 1.05; color: #fff; direction: ltr; unicode-bidi: isolate; }
[dir=rtl] .certb b { text-align: right; }
.certb span { font-size: 21px; font-weight: 600; color: #D9DCE4; margin-top: 4px; }
.certb.sm b { font-size: 30px; } .certb.sm span { font-size: 19px; } .certb.sm .cb-bar { width: 4px; }
.certb.big b { font-size: 50px; } .certb.big span { font-size: 26px; margin-top: 6px; } .certb.big .cb-bar { width: 6px; }
.hi-adv, .d-adv { margin-top: 18px; font-size: inherit; }
#pcert, #pcert.on { background: none; border: 0; box-shadow: none; padding: 0; }
.seriesd .s-low { transform: translate3d(0, 350px, 0); }
.seriesd.in-eps .s-low { transform: translate3d(0, 0, 0); }
.seriesd .s-top .kicker { margin-bottom: 0; }
.seriesd .d-adv { margin-top: 12px; }
.seriesd.in-eps .d-adv { visibility: hidden; }
#pcert, #pcert.on { padding: 26px 34px; background: radial-gradient(ellipse at center, rgba(0,0,0,.5) 0%, rgba(0,0,0,.25) 45%, rgba(0,0,0,0) 72%); }
/* the section you are in: the app's green (white only while the bar has the focus on it) */
.tn-item.cur, .tn-round.cur { background: linear-gradient(180deg, #6EE7A0, #34C46E); color: #04120A; font-weight: 700; box-shadow: inset 0 1px 0 rgba(255,255,255,.45), 0 6px 18px rgba(52,196,110,.35); }
.tn-item.cur.focus, .tn-round.cur.focus { background: #fff; color: #07090F; }

/* =====================================================================
   "Who's watching?" (the servers)
   ===================================================================== */
.profiles { background: radial-gradient(ellipse 70% 55% at 50% 38%, #18264A 0%, #0C1328 55%, #06080F 100%); }
.profiles .pr-glow { position: absolute; left: 0; right: 0; top: 0; bottom: 0; pointer-events: none;
  background: radial-gradient(circle at 18% 12%, rgba(74,222,128,.10), rgba(74,222,128,0) 32%), radial-gradient(circle at 85% 85%, rgba(56,189,248,.10), rgba(56,189,248,0) 35%); }
.profiles .pr-logo { position: absolute; top: 58px; left: 50%; transform: translateX(-50%); height: 40px; }
.profiles .pr-title { position: absolute; top: 150px; left: 0; right: 0; text-align: center; font-size: 66px; font-weight: 700; letter-spacing: -.5px; text-shadow: 0 6px 30px rgba(0,0,0,.5); }
.profiles .pr-sub { position: absolute; top: 250px; left: 0; right: 0; text-align: center; font-size: 25px; color: #8E97AB; }
.profiles .pr-view { position: absolute; top: 340px; left: 0; right: 0; height: 640px; overflow: hidden; }
.profiles .pr-wrap { position: absolute; top: 30px; left: 50%; width: 1440px; margin-left: -720px; display: flex; flex-wrap: wrap; justify-content: center; align-content: flex-start;
  transition: transform .3s cubic-bezier(.2,.8,.2,1); }
.prof { width: 288px; height: 330px; display: flex; flex-direction: column; align-items: center; text-align: center; }
.prof .pa { position: relative; width: 196px; height: 196px; border-radius: 30px; display: flex; align-items: center; justify-content: center; overflow: hidden;
  box-shadow: 0 16px 40px rgba(0,0,0,.45); transition: transform .16s ease-out, box-shadow .16s ease-out; }
.prof .pgloss { position: absolute; left: 0; right: 0; top: 0; height: 55%; background: linear-gradient(180deg, rgba(255,255,255,.28), rgba(255,255,255,0)); }
.prof .pi { position: relative; font-size: 104px; font-weight: 700; color: rgba(7,9,15,.88); line-height: 1; }
.prof .pdot { position: absolute; top: 14px; right: 14px; width: 20px; height: 20px; border-radius: 10px; background: #fff; box-shadow: 0 0 0 4px rgba(7,9,15,.35); }
.prof .pn { margin-top: 24px; font-size: 29px; font-weight: 700; color: #9AA3B5; max-width: 270px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color .16s; }
.prof .pt { margin-top: 4px; font-size: 20px; color: #626C82; }
.prof.on .pt { color: #4ADE80; }
.prof.add .pa { background: rgba(255,255,255,.04); border: 3px dashed rgba(255,255,255,.28); box-shadow: none; }
.prof.add .pplus { font-size: 96px; font-weight: 300; color: #9AA3B5; line-height: 1; margin-top: -8px; }
.prof.focus .pa { transform: scale(1.1); box-shadow: 0 0 0 6px #fff, 0 24px 60px rgba(0,0,0,.6); }
.prof.add.focus .pa { border-color: transparent; background: rgba(255,255,255,.12); }
.prof.add.focus .pplus { color: #fff; }
.prof.focus .pn { color: #fff; }
.profiles .hint { position: absolute; bottom: 46px; left: 50%; right: auto; transform: translateX(-50%); }
.profiles .pr-view { -webkit-mask-image: linear-gradient(180deg, transparent 0, #000 26px, #000 calc(100% - 10px), transparent 100%); }
.profiles .pr-view.one .pr-wrap { top: 120px; }
